
/*
This file is used to display graph on the left side of the screen on the oscilloscope page. 
This is done with the use of paperJS. 
All that is done is the lines are place on the max and min points of the graph area.
Then a loop is ran to place the intersecting lines of the graph.
*/

import Paper from "paper";

/*
 * DrawGraph
 *
 * This file is used to display graph on the left side of the 
 * screen on the oscilloscope page. This is done with the use 
 * of paperJS. All that is done is the lines are place on the 
 * max and min points of the graph area, then a loop is ran 
 * to place the intersecting lines of the graph.
 * 
 * @param isSpectrumGraph: boolean   Draws a spectrum graph if true.
 */
const DrawGraph = (isSpectrumGraph) => {

  // Start a new Layer
  let graphLayer = new Paper.Layer();

  // Function to draw gridlines
  var drawGridLines = function (width, height, boundingRect) {
    var width_per_rectangle = boundingRect.width / width;
    var height_per_rectangle = boundingRect.height / height;
    var hatchLengthFactor = 0.012;
		
		//set up vertical grid lines
		for (let i = 0; i <= width; i++) {
			let xPos = boundingRect.left + i * width_per_rectangle;
			let topPoint = new Paper.Point(xPos, boundingRect.top);
			let bottomPoint = new Paper.Point(xPos, boundingRect.bottom);
			let aLine = new Paper.Path.Line(topPoint, bottomPoint);
			aLine.strokeColor = "black";
			aLine.strokeWidth = 0.6;

			//vertical center line and hatch marks
			if (i === 5) {
				aLine.strokeWidth = 1.5;

				//already have xPos
				let yPos = boundingRect.top;
				let oldyPos = yPos;
				let oldxPos = xPos;

				//create hatch marks for vertical center line
				for (let hatchMark = 0; hatchMark < 40; hatchMark++) {
					xPos = oldxPos;

					let yPos = (boundingRect.height * hatchMark) / 40;

					xPos = xPos * (1 - hatchLengthFactor); //make a point to the left of the center line
					let hatch1 = new Paper.Point(xPos, yPos);
					xPos = xPos * (1 + 2 * hatchLengthFactor); //make a point to the right of the center line
					let hatch2 = new Paper.Point(xPos, yPos);
					let connect = new Paper.Path.Line(hatch1, hatch2);
					connect.strokeColor = "black";
					connect.strokeWidth = 0.8;
				}
			}
			//set bold lines
			if (i === 0 || i === width) {
				aLine.strokeWidth = 1.5;
			}
		}

		//set up horizontal grid lines
		let horizontalCenterLine = isSpectrumGraph ? (height / 4) : height / 2;
		for (let i = 0; i <= height; i++) {
			let yPos = boundingRect.top + i * height_per_rectangle;
			let leftPoint = new Paper.Point(boundingRect.left, yPos);
			let rightPoint = new Paper.Point(boundingRect.right, yPos);
			let aLine = new Paper.Path.Line(leftPoint, rightPoint);
			aLine.strokeColor = "black";
			aLine.strokeWidth = 0.6;

			//horizontal center line
			if (i === horizontalCenterLine) {
				aLine.strokeWidth = 1.5;

				//create increments to space out hatch marks evenly
				let incx = boundingRect.width / 40;

				//already have yPos
				let xPos = boundingRect.left;
				let oldyPos = yPos;
				let oldxPos = xPos;
				
				//create hatch marks for horizontal center line
				for (let hatchMark = 1; hatchMark <= 40; hatchMark++) {
					xPos = oldxPos;
					yPos = oldyPos;
					xPos = xPos + hatchMark * incx;
					yPos = yPos * (1 - hatchLengthFactor); //make a point to the left of the center line
					let hatch1 = new Paper.Point(xPos, yPos);
					yPos = yPos * (1 + 2 * hatchLengthFactor); //make a point to the right of the center line
					let hatch2 = new Paper.Point(xPos, yPos);
					let connect = new Paper.Path.Line(hatch1, hatch2);
					connect.strokeColor = "black";
					connect.strokeWidth = 0.8;
				}
			}
			//set bold lines
			if (i === 0 || i === height) {
				aLine.strokeWidth = 2.5;
			}
		}
	};
	let numOfWBoxes = 10;
	let numOfHBoxes = 8;
	drawGridLines(numOfWBoxes, numOfHBoxes, Paper.view.bounds);

	// Redraw on resize
	Paper.view.on("resize", function (event) {
		graphLayer.activate();
		graphLayer.removeChildren();
		drawGridLines(numOfWBoxes, numOfHBoxes, Paper.view.bounds);
	});
};

export default DrawGraph;
