import { isPlatform } from "@ionic/react";
import { serialConnection } from "./Serial";
import { setupMicrophonePermission } from "./microphone";

export function setupWaveDataPopulation(channel1, channel2, fillDataArrayInterval) {
    serialConnection.setAnalogMode();

    if (isPlatform("mobile") && window.audioinput) {
        setupMicrophonePermission();
        window.addEventListener("audioinput", async (evt) => {
            if (channel1._drawing && !serialConnection.isConnected) {
                const eventData = evt.data;
                for (let i = 0; i < channel1._data.length; i++) {
                    channel1._data[i] = eventData[i];
                }
            }
        });
        (function loop() {
            setTimeout(async () => {
                if ((channel1._drawing || channel2._drawing) && serialConnection.isConnected) {
                    await serialConnection.analogRead(channel1._data, channel2._data);
                }
                loop();
            }, 20);
        })();
    // Web
    } else {
        const constraints = { audio: {autoGainControl: false, echoCancellation: false,  noiseSuppression: false}};
        navigator.mediaDevices.getUserMedia(constraints)
        .then(function(mediaStream) {
            let ctx = new AudioContext({sampleRate: 44100});
            let mic = ctx.createMediaStreamSource(mediaStream);
            let spe = ctx.createAnalyser();
            spe.fftSize = channel1._bufferSize;
            mic.connect(spe);

            let osc = ctx.createOscillator();
            osc.type = 'sine';
            osc.frequency.value = 440;

            (function loop() {
                setTimeout(async () => {
                    if ((channel1._drawing || channel2._drawing) && serialConnection.isConnected) {
                        await serialConnection.analogRead(channel1._data, channel2._data);
                    } else if (channel1._drawing) {
                        spe.getFloatTimeDomainData(channel1._data);
                    }
                    loop();
                }, 20);
            })();
        })
        .catch((err) => {
            console.log(`${err.name}:  ${err.message}`);
        });
    }
}
