import {
	IonHeader,
	IonButtons,
	IonToolbar,
	IonMenuButton,
	IonLabel,
	IonTitle,
	IonImg,
	IonButton,
	IonPopover,
	isPlatform,
	IonItem,
	IonList,
	IonSelect,
	IonSelectOption,
	useIonAlert
} from "@ionic/react";
import FullscreenButton from "../buttons/FullscreenButton";
import ConnectButton from "../buttons/ConnectButton";
import React, { useEffect, useState } from "react";
import { useHistory } from "react-router-dom";
import SettingsProperty from "../enums/SettingsProperty";
import { serialConnection } from "../components/Serial"

const MAX_SAMPLE_RATE = 1000000;

type Props = {
	name: string,
	hidden: boolean,
	isConnectHidden: boolean,
	onFullscreenClick?: () => void,
	onSettingsChange?:(property: SettingsProperty, value: any) => void,
	tutorialPath?: string,
	isSettingHidden?: boolean
};

const PageHeader: React.FC<Props> = (props: Props) => {
	const [present] = useIonAlert();
	const history = useHistory(); // Instantiate useHistory

	const [isSettingsPopoverHidden, setIsSettingsPopoverHidden] = useState(true);
	const [hardwareScaler, setHardwareScaler] = useState(1);
	const [singleChannelSampleRate, setSingleChannelSampleRate] = useState(MAX_SAMPLE_RATE);
	const [singleChannelSampleTime, setSingleChannelSampleTime] = useState(1);
	const [dualChannelSampleRate, setDualChannelSampleRate] = useState(MAX_SAMPLE_RATE / 2);
	const [dualChannelSampleTime, setDualChannelSampleTime] = useState(2);

	function handleSerialError(error: Error){
		present({
			cssClass: "alert",
			header: "Serial Error",
			message: error.message,
			buttons: [
			{
				text: "Learn More",
				handler: () => {} // TODO: LINK TO HUSKER-SCOPE WIKI
			},
			{
				text: "I understand",
				handler: () => {}
			}]
		})
	}

	function handleTutorialClick() {
		history.push(`/page/Tutorial/?${props.tutorialPath}`); // Navigate to the Tutorial page
	}

	useEffect(()=>{
		setSingleChannelSampleRate(MAX_SAMPLE_RATE / hardwareScaler);
		setSingleChannelSampleTime(hardwareScaler);
		setDualChannelSampleRate(MAX_SAMPLE_RATE / (hardwareScaler * 2));
		setDualChannelSampleTime(hardwareScaler * 2);
	}, [hardwareScaler]);

	function handleConfirm(){
		setIsSettingsPopoverHidden(true);
		if(!props.onSettingsChange) return;
		props.onSettingsChange(SettingsProperty.eHardwareBoardScaler, hardwareScaler);
		props.onSettingsChange(SettingsProperty.eSingleChannelSampleRate, singleChannelSampleRate);
		props.onSettingsChange(SettingsProperty.eSingleChannelSampleTime, singleChannelSampleTime);
		props.onSettingsChange(SettingsProperty.eDualChannelSampleRate, dualChannelSampleRate);
		props.onSettingsChange(SettingsProperty.eDualChannelSampleTime, dualChannelSampleTime);
		serialConnection.setHardwareScaler(hardwareScaler);
	}

	return (
		<IonHeader className={props.hidden ? "header-full" : "header"}>
			<IonToolbar mode="ios" color="primary">
				<IonButtons slot="start">
					<IonMenuButton />
					<ConnectButton
						hidden={props.isConnectHidden}
						onError={(error) => handleSerialError(error) }
					/>
					{props.tutorialPath && <IonButton onClick={handleTutorialClick}>Tutorial</IonButton>} {/* Add the Tutorial button */}
				</IonButtons>
				<IonTitle> <b style={{fontWeight: "bolder"}}>Husker Scope</b>{": " + props.name}</IonTitle>

				<IonButton className="settings-button"
					 onClick={() => setIsSettingsPopoverHidden(false) }
					 hidden={props.isConnectHidden || props.isSettingHidden}
					 mode="ios"
					 fill="clear"
				>
					<img className="toolbar-img" src={process.env.PUBLIC_URL + "/assets/settings.png"} alt=""></img>
				</IonButton>

				{props.onFullscreenClick
					? <FullscreenButton hidden={props.isConnectHidden} onClick={props.onFullscreenClick}/>
					: <IonImg slot="end" class="logo" src={process.env.PUBLIC_URL + "/assets/Husker_Scope_Logo_circle.png"}/>
				}
			</IonToolbar>

			{/* Settings Popover */}
			<IonPopover
				isOpen={!isSettingsPopoverHidden}
				className={isPlatform("mobile") ? "input-popover2" : "settings-popover"}
				mode="ios"
				showBackdrop={true}
				onDidDismiss={() => setIsSettingsPopoverHidden(true)}
			>
					<div className="popover-setting-content">
						<div className="popover-setting-row">
							<IonList className="popover-setting-list">
								<IonItem className="popover-setting-item" lines="none" color="none">
									<IonLabel
										className="popover-setting-button"
										data-testid="Rising-confirm">
										Hardware Board Scaler
									</IonLabel>
									<IonSelect
										className="popover-setting-select"
										value={hardwareScaler}
										onIonChange={(event) => setHardwareScaler(event.detail.value)}
									>
										<IonSelectOption value={ 1 }> { `${1}` } </IonSelectOption>
										<IonSelectOption value={ 2 }> { `${2}` } </IonSelectOption>
										<IonSelectOption value={ 3 }> { `${3}` } </IonSelectOption>
										<IonSelectOption value={ 4 }> { `${4}` } </IonSelectOption>
										<IonSelectOption value={ 5 }> { `${5}` } </IonSelectOption>
										<IonSelectOption value={ 6 }> { `${6}` } </IonSelectOption>
										<IonSelectOption value={ 7 }> { `${7}` } </IonSelectOption>
										<IonSelectOption value={ 8 }> { `${8}` } </IonSelectOption>
										<IonSelectOption value={ 9 }> { `${9}` } </IonSelectOption>
										<IonSelectOption value={ 10 }> { `${10}` } </IonSelectOption>
									</IonSelect>
								</IonItem>
							</IonList>
						</div>

						<div className="popover-setting-row">
							<IonList className="popover-setting-list">
								<IonItem className="popover-setting-item" lines="none" color="none">
									<IonLabel
										className="popover-setting-button"
										data-testid="Auto-confirm">
										Single Channel Sample Rate (Hz)
									</IonLabel>
									<IonSelect
										className="popover-setting-select"
										disabled={true}
										value={singleChannelSampleRate}
										// onIonChange={(event) => setSelectedSampleSize(event.detail.value)}
									>
										<IonSelectOption value={ MAX_SAMPLE_RATE }> { `${ MAX_SAMPLE_RATE }` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 2 }> { `${ MAX_SAMPLE_RATE / 2}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 3 }> { `${MAX_SAMPLE_RATE / 3}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 4 }> { `${MAX_SAMPLE_RATE / 4}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 5 }> { `${MAX_SAMPLE_RATE / 5}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 6 }> { `${MAX_SAMPLE_RATE / 6}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 7 }> { `${MAX_SAMPLE_RATE / 7}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 8 }> { `${MAX_SAMPLE_RATE / 8}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 9 }> { `${MAX_SAMPLE_RATE / 9}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / 10 }> { `${MAX_SAMPLE_RATE / 10}` } </IonSelectOption>

									</IonSelect>
								</IonItem>
							</IonList>
						</div>

						<div className="popover-setting-row">
							<IonList className="popover-setting-list">
								<IonItem className="popover-setting-item" lines="none" color="none">
									<IonLabel
										className="popover-setting-button"
										data-testid="Auto-confirm">
										Single Channel Sample Time (us)
									</IonLabel>
									<IonSelect
										className="popover-setting-select"
										disabled={true}
										value={singleChannelSampleTime}
										// onIonChange={(event) => setSelectedSampleSize(event.detail.value)}
									>
										<IonSelectOption value={ 1 }>{ `${1}` } </IonSelectOption>
										<IonSelectOption value={ 2 }>{ `${2}` } </IonSelectOption>
										<IonSelectOption value={ 3 }>{ `${3}` } </IonSelectOption>
										<IonSelectOption value={ 4 }>{ `${4}` } </IonSelectOption>
										<IonSelectOption value={ 5 }>{ `${5}` } </IonSelectOption>
										<IonSelectOption value={ 6 }>{ `${6}` } </IonSelectOption>
										<IonSelectOption value={ 7 }>{ `${7}` } </IonSelectOption>
										<IonSelectOption value={ 8 }>{ `${8}` } </IonSelectOption>
										<IonSelectOption value={ 9 }>{ `${9}` } </IonSelectOption>
										<IonSelectOption value={ 10 }>{ `${10}` } </IonSelectOption>
									</IonSelect>
								</IonItem>
							</IonList>
						</div>

						<div className="popover-setting-row">
							<IonList className="popover-setting-list">
								<IonItem className="popover-setting-item" lines="none" color="none">
									<IonLabel
										className="popover-setting-button"
										data-testid="Auto-confirm">
										Dual Channel Sample Rate (Hz)
									</IonLabel>
									<IonSelect
										className="popover-setting-select"
										disabled={true}
										value={dualChannelSampleRate}
										// onIonChange={(event) => setSelectedSampleSize(event.detail.value)}
									>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (1 * 2) }>{ `${MAX_SAMPLE_RATE / (1 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (2 * 2) }>{ `${MAX_SAMPLE_RATE / (2 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (3 * 2) }>{ `${MAX_SAMPLE_RATE / (3 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (4 * 2) }>{ `${MAX_SAMPLE_RATE / (4 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (5 * 2) }>{ `${MAX_SAMPLE_RATE / (5 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (6 * 2) }>{ `${MAX_SAMPLE_RATE / (6 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (7 * 2) }>{ `${MAX_SAMPLE_RATE / (7 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (8 * 2) }>{ `${MAX_SAMPLE_RATE / (8 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (9 * 2) }>{ `${MAX_SAMPLE_RATE / (9 * 2)}` } </IonSelectOption>
										<IonSelectOption value={ MAX_SAMPLE_RATE / (10 * 2) }>{ `${MAX_SAMPLE_RATE / (10 * 2)}` } </IonSelectOption>
									</IonSelect>
								</IonItem>
							</IonList>
						</div>

						<div className="popover-setting-row">
							<IonList className="popover-setting-list">
								<IonItem className="popover-setting-item" lines="none" color="none">
									<IonLabel
										className="popover-setting-button"
										data-testid="Auto-confirm">
										Dual Channel Sample Time (us)
									</IonLabel>
									<IonSelect
										className="popover-setting-select"
										disabled={true}
										value={dualChannelSampleTime}
										// onIonChange={(event) => setSelectedSampleSize(event.detail.value)}
									>
										<IonSelectOption value={ 2 }>{ `${2}` } </IonSelectOption>
										<IonSelectOption value={ 4 }>{ `${4}` } </IonSelectOption>
										<IonSelectOption value={ 6 }>{ `${6}` } </IonSelectOption>
										<IonSelectOption value={ 8 }>{ `${8}` } </IonSelectOption>
										<IonSelectOption value={ 10 }>{ `${10}` } </IonSelectOption>
										<IonSelectOption value={ 12 }>{ `${12}` } </IonSelectOption>
										<IonSelectOption value={ 14 }>{ `${14}` } </IonSelectOption>
										<IonSelectOption value={ 16 }>{ `${16}` } </IonSelectOption>
										<IonSelectOption value={ 18 }>{ `${18}` } </IonSelectOption>
										<IonSelectOption value={ 20 }>{ `${20}` } </IonSelectOption>
									</IonSelect>
								</IonItem>
							</IonList>
						</div>

						<div className="popover-setting-row" color="#d00000">
							<IonButton
								onClick={() => handleConfirm() }
								className="confirm-settings-button"
							>
									Confirm
							</IonButton>
						</div>
					</div>
				</IonPopover>
		</IonHeader>
	);
};

export default PageHeader;