/**
 * Camp the value between bounds
 *
 * This will check that
 *   min <= value <= max
 * If the value is in the range then it return itself
 * If the value more than the max range it should return the max value.
 * If the value is less than the min range it should return the min value.
 * 
 * @param  value: number        Value to clamp
 * @param  min:   number        The minimum value to clamp.
 * @param  max:   number        The Maximum value to clamp
 * @return number               The clamped value
 */
export function clamp(value: number, min: number, max: number) {
  return Math.min(Math.max(value, min), max);
}
