/*
This file is used to display wave on the left side of the
screen on the logic analyzer page. This is done with the
use of paperJS and AudioContext. We will look for the
access to the users microphone, then for each (1/sampleRate)
seconds we will pull in the current audio value. Theses vales
are place in a buffer which are then put on the graph to show
the current value of buffer.
*/

import Paper from "paper";
import { serialConnection } from "./Serial";
import * as helper from '../utils/helper.js';
import { isPlatform } from "@ionic/react";
import DecodingMode from "../enums/DecodingMode";

// Use Effects
let playing = true;
let zoomLevel = 1;
let numberOfSamples = 5000;
let sampleRate = 10000;
let currentLeft = 0;
let currentRight = numberOfSamples;
let cursorPosition = {x: 0, y: 0};
let decodingMode = DecodingMode.eDisabled;
let decodingChannel = 0;

let channelsData = {
  length: 0,
  channel1: new ArrayBuffer(numberOfSamples),
  channel2: new ArrayBuffer(numberOfSamples),
  channel3: new ArrayBuffer(numberOfSamples),
  channel4: new ArrayBuffer(numberOfSamples),
  channel5: new ArrayBuffer(numberOfSamples),
  channel6: new ArrayBuffer(numberOfSamples),
  channel7: new ArrayBuffer(numberOfSamples),
  channel8: new ArrayBuffer(numberOfSamples)
};

let channels = undefined;

export function setPlaying(val) {
  playing = val;
  if (val) {
    clearChannels();
    serialConnection.setDigitalMode();
  } else {
    serialConnection.sampleStop();
  }
}

export function setZoomLevel(level) {
  zoomLevel = level;
}

export function setNumberOfSamples(s) {
  numberOfSamples = s;
  clearChannels();
}

export function setSampleRate(rate) {
  sampleRate = rate;
  serialConnection.setHardwareScaler(1000000 / rate);
  clearChannels();
}

export function setCurrentLeft(val) {
  currentLeft = val;
}

export function setCurrentRight(val) {
  currentRight = val;
}

export function setDecodingState(mode, channel) {
  decodingMode = mode;
  decodingChannel = channel;
}

export const callReDraw = () => {
  if(channels) {
    channels.init();
    channels.update();
  }
}

function clearChannels() {
  channelsData.length = 0;
  for (let b = 0; b < 8; b++) {
    channelsData[`channel${b + 1}`] = new ArrayBuffer(numberOfSamples);
  }
  if (channels) {
    channels.init();
  }
}

async function readDigital(setPlayingCallback) {
  if (!serialConnection.isConnected || !playing) {
    return;
  }

  const data = await serialConnection.digitalRead();

  if (!data) {
    return;
  }

  for (let i = 0; i < data.length; i++) {
    if (channelsData.length >= numberOfSamples) {
      setPlayingCallback(false);
      return;
    }

    for (let b = 0; b < 8; b++) {
      let arrayBuffer = channelsData[`channel${b + 1}`];
      let int8Array = new Int8Array(arrayBuffer);
      int8Array[channelsData.length] = helper.convertLogicToFloat(data[i], b + 1);
    }

    channelsData.length += 1;
  }
}

export const drawLogicAnalyzerWave = async (setPlayingCallback) => {
  await serialConnection.setDigitalMode();

  // Continuously poll for digital data
  (function loop() {
    setTimeout(async () => {
        try {
          await readDigital(setPlayingCallback);
        } catch (error) {
          console.log(error);
        }
        loop();
    }, 10);
  })();

  // Initialize Paper.js wave layer and draw the signals
  let waveLayer = new Paper.Layer();
  channels = new Wave();
  if (channels) {
      channels.init();
  }

  const updatePosition = (event) => {
    const padding = 12 * 2;
    const viewBounds = Paper.view.bounds;
    const scaleX = viewBounds.width / (viewBounds.width - (padding * 2));
    const scaleY = viewBounds.height / (viewBounds.height - (padding * 2));
    cursorPosition.x = (event.point.x - padding) * scaleX;
    cursorPosition.y = (event.point.y - padding) * scaleY;
  };

  if (isPlatform('mobile')) {
      // Mobile devices: track taps
      Paper.view.onMouseDown = updatePosition;
  } else {
      // Desktop devices: track hover
      Paper.view.onMouseMove = updatePosition;
  }

  // Draw the signals on each frame
  Paper.view.on('frame', function (event) {
    channels.init();
    waveLayer.activate();
    channels.update();
  });

  // Handle resizing of the view (for example, in full-screen mode)
  Paper.view.on('resize', function (event) {
      waveLayer = new Paper.Layer();
      waveLayer.activate();
      if (channels) {
          channels.init();
      }
  });
};

function timeToText(time) {
  if (time < 0.001) {
    const utime = time * 1000000;
    return `${utime.toFixed(0)}us`;
  } else {
    const mtime = time * 1000;
    return `${mtime.toFixed(1)}ms`;
  }
}

// Decoding Functions: These functions decode and generate an array of non-overlapping decoding events

/**
 * A generic object describing events in the decoded signal
 *
 * @param {number} start The sample index where the event starts
 * @param {number} end The sample index where the event ends
 * @param {string} text The text describing the number
 */
function DecodingEvent(start, end, text) {
  this.start = start;
  this.end = end;
  this.text = text;
}

function decodeTiming(channelIndex, start, end) {
  const arrayBuffer = channelsData[`channel${channelIndex + 1}`];
  const data = new Int8Array(arrayBuffer);

  let events = [];

  let realStart = 0;
  for (let i = start-1; i > 0; i--) {
    if (data[i] !== data[i+1]) {
      realStart = i;
      break;
    }
  }

  let startPos = realStart;
  for (let i = realStart; i < end; i++) {
    if (data[i] !== data[i+1]) {
      const eventLength = (i - startPos) + 1;
      const eventTime = eventLength * (1.0 / sampleRate);
      const text = timeToText(eventTime);
      events.push(new DecodingEvent(startPos, i, text));
      startPos = i + 1;
    }
  }

  return events;
}

/**
 * Decodes PWM signals
 *
 * @param {number} channelIndex The channel to decode
 * @param {number} start Where to start looking for events (inclusive)
 * @param {number} end Where to end looking for events (exclusive)
 * @returns {Array<DecodingEvent>} An array of decoding events
 */
function decodePwm(channelIndex, start, end) {
  const arrayBuffer = channelsData[`channel${channelIndex + 1}`];
  const data = new Int8Array(arrayBuffer);

  let events = [];

  // Search for falling edges
  for (let i = start; i < end; i++) {
    const current = data[i];
    const next = data[i + 1];
    if (current > 0 && next < 0) {
      let eventStart = 0;
      for (let j = i - 1; j > eventStart; j--) {
        if (data[j] < 0) {
          eventStart = j + 1;
          break;
        }
      }

      let eventEnd = numberOfSamples - 1;
      for (let j = i + 2; j < eventEnd; j++) {
        if (data[j] > 0) {
          eventEnd = j - 1;
          break;
        }
      }

      const eventHigh = (i - eventStart) + 1;
      const eventLength = (eventEnd - eventStart) + 1;
      const dutyPercent = (eventHigh / eventLength) * 100;
      const text = `${dutyPercent.toFixed(0)}%`;

      events.push(new DecodingEvent(eventStart, eventEnd, text));
    }
  }

  return events;
}

export class Wave {
  colors = ["red", "blue", "green"];

  constructor() {
    this._paths = Array.from({ length: 8 }, () => new Paper.Path());
    this._paths.forEach((path, index) => {
      path.strokeColor = this.colors[index % this.colors.length];
      path.strokeWidth = 1.8;
      path.selected = false;
      path.closed = false;
    });
    this._tempPaths = [];
  }

  init() {
    this._paths.forEach(path => {
      path.segments = [];
    });
    this._tempPaths.forEach(path => {
      path.remove();
    });
    this._tempPaths = [];
  }

  update(_event) {
    const createTempLine = (color, width, xStart, yStart, xEnd, yEnd) => {
      let path = new Paper.Path();
      path.strokeColor = color;
      path.strokeWidth = width;
      path.selected = false;
      path.closed = false;

      path.add([xStart, yStart]);
      path.add([xEnd, yEnd]);

      this._tempPaths.push(path);
    };

    const height = Paper.project.activeLayer.view.size.height;
    const width = Paper.project.activeLayer.view.size.width;

    const decodingEnabled = (decodingMode !== DecodingMode.eDisabled);
    const channels = decodingEnabled ? 9 : 8;

    const channelHeight = height / channels;
    const drawingOffset = channelHeight * 0.40;

    const currentWidth = Math.pow(2, zoomLevel - 1);
    const bitWidth = width / (numberOfSamples / currentWidth);

    const hoveredX = currentLeft + Math.trunc(cursorPosition.x / bitWidth);

    for (let channelIndex = 0; channelIndex < 8; channelIndex++) {
      const yMiddle = channelHeight * (channelIndex + 0.5);
      const yHigh = yMiddle - drawingOffset;
      const yLow = yMiddle + drawingOffset;

      let hoveredY = false;
      if (yLow > cursorPosition.y && yHigh < cursorPosition.y){
        hoveredY = true;
      }

      let arrayBuffer = channelsData[`channel${channelIndex + 1}`];
      let data = new Int8Array(arrayBuffer);
      let path = this._paths[channelIndex];

      const right = Math.min(currentRight, numberOfSamples - 1);

      let start = currentLeft;

      while (start <= right) {
        let end = start + 1;
        while (end < currentRight && data[start] === data[end]) {
          end += 1;
        }

        const y = data[start] > 0 ? yHigh : yLow;
        const xStart = Math.round((start - currentLeft) * bitWidth);
        const xEnd = Math.round((end - currentLeft) * bitWidth);

        path.add([xStart, y]);
        path.add([xEnd, y]);

        start = end;
      }

      if (zoomLevel > 5) {
        for (let i = currentLeft; i <= right; i++) {
          const x = Math.round(((i - currentLeft) * bitWidth) + (bitWidth / 2));
          const y = data[i] > 0 ? yHigh : yLow;
          const color = this.colors[channelIndex % 3];
          createTempLine(color, 2, x, y + 3, x, y - 3);
        }
      }

      if (hoveredY) {
        const hoveredValue = data[hoveredX];

        let previousEdge = -1;
        for (let i = hoveredX - 1; i >= 0; i--) {
          const diff = (data[i] > 0 && hoveredValue <= 0) || (data[i] <= 0 && hoveredValue > 0);
          if (diff) {
            previousEdge = i;
            break;
          }
        }

        let nextEdge = numberOfSamples;
        for (let i = hoveredX + 1; i <= numberOfSamples; i++) {
          const diff = (data[i] > 0 && hoveredValue <= 0) || (data[i] <= 0 && hoveredValue > 0);
          if (diff) {
            nextEdge = i;
            break;
          }
        }

        let nextNextEdge = numberOfSamples;
        for (let i = nextEdge + 1; i <= numberOfSamples; i++) {
          const same = (data[i] > 0 && hoveredValue > 0) || (data[i] <= 0 && hoveredValue <= 0);
          if (same) {
            nextNextEdge = i;
            break;
          }
        }

        const arrowLeft = Math.max(previousEdge, currentLeft - 1);
        const arrowRight = Math.min(nextEdge, currentRight + 1);
        const arrowRight2 = Math.min(nextNextEdge, currentRight + 1);

        const arrowStartX = Math.round((arrowLeft - currentLeft + 1) * bitWidth);
        const arrowEndX = Math.round((arrowRight - currentLeft) * bitWidth);
        const arrowEndX2 = Math.round((arrowRight2 - currentLeft) * bitWidth);

        const arrowOffset = Math.round(Math.abs(yHigh - yLow) * 0.1);
        const arrowYHigh = yHigh - arrowOffset;
        const arrowYLow = yLow + arrowOffset;

        const createArrowPath = (xStart, yStart, xEnd, yEnd) => {
          createTempLine("black", 3, xStart, yStart, xEnd, yEnd);
        };

        createArrowPath(arrowStartX, arrowYHigh, arrowEndX, arrowYHigh);
        createArrowPath(arrowStartX, arrowYHigh, arrowStartX, arrowYHigh + 5);
        createArrowPath(arrowEndX, arrowYHigh, arrowEndX, arrowYHigh + 5);

        createArrowPath(arrowStartX, arrowYLow, arrowEndX2, arrowYLow);
        createArrowPath(arrowStartX, arrowYLow, arrowStartX, arrowYLow - 5);
        createArrowPath(arrowEndX2, arrowYLow, arrowEndX2, arrowYLow - 5);

        const createArrowLabel = (left, right, y, above) => {
          const numSamples = right - left - 1;
          const time = numSamples / sampleRate;

          const text = timeToText(time);
          const fontSize = Math.min(drawingOffset, 18);

          const center = (left + right) / 2;
          const xPos = ((center - currentLeft) * bitWidth) + (bitWidth / 2);
          const yPos = y + (above ? -3 : fontSize - 1);
          const pos = new Paper.Point(xPos, yPos);

          let pointText = new Paper.PointText(pos);
          pointText.justification = 'center';
          pointText.fillColor = 'black';
          pointText.fontSize = fontSize;
          pointText.fontWeight = 'bold';
          pointText.content = text;

          this._tempPaths.push(pointText);
        };

        createArrowLabel(arrowLeft, arrowRight, yHigh, false);
        createArrowLabel(arrowLeft, arrowRight2, yLow, true);
      }
    }

    if (decodingEnabled) {
      const yMiddle = channelHeight * 8.5;
      const yHigh = yMiddle - drawingOffset;
      const yLow = yMiddle + drawingOffset;

      const decodingLineWidth = 3;
      createTempLine("black", decodingLineWidth, 0, yHigh, width, yHigh);
      createTempLine("black", decodingLineWidth, 0, yLow, width, yLow);

      let events = [];
      if (decodingMode === DecodingMode.ePWM) {
        events = decodePwm(decodingChannel, currentLeft, currentRight);
      } else if (decodingMode === DecodingMode.eTiming) {
        events = decodeTiming(decodingChannel, currentLeft, currentRight);
      }

      events.forEach((event) => {
        const xStart = Math.max((event.start - currentLeft) * bitWidth, 0);
        const xEnd = Math.min((event.end - currentLeft + 1) * bitWidth, width);

        createTempLine("black", 3, xStart, yHigh, xStart, yLow);
        createTempLine("black", 3, xEnd, yHigh, xEnd, yLow);

        const fontSize = channelHeight * 0.3;

        const textX = (xStart + xEnd) / 2;
        const textY = yMiddle + (fontSize * 0.4);
        const textPos = new Paper.Point(textX, textY);

        const clippingRect = new Paper.Rectangle([xStart, yHigh], [xEnd - xStart, channelHeight]);
        const clippingPath = new Paper.Path.Rectangle(clippingRect);

        let pointText = new Paper.PointText(textPos);
        pointText.justification = 'center';
        pointText.fillColor = 'black';
        pointText.fontSize = fontSize;
        pointText.fontWeight = 'bold';
        pointText.content = event.text;

        let group = new Paper.Group(clippingPath, pointText);
        group.clipped = true;

        this._tempPaths.push(group);
      });
    }
  }
}