import { IonButton, IonPopover, isPlatform } from "@ionic/react";
import React from "react";
import '../pages/Pages.css';

type Props = {
  hidden: boolean,
  buttonLabels: Array<string>,
  onButtonPressed: (value: string | undefined) => void,
};

const SelectFromOptionsPopover: React.FC<Props> = ({ hidden, buttonLabels, onButtonPressed }) => {

  const isMobile = isPlatform("ios") || isPlatform("android");
  const buttons = buttonLabels.map((label) =>
    <IonButton className="trigger-popup-button" key={label}
      onClick={() => onButtonPressed(label)}>
      {label}
    </IonButton>
  );
  
  return (
    
    <IonPopover
      isOpen={!hidden}
      className={isMobile ? "input-popover2" : "input-popover2-web"}
      mode="ios"
      showBackdrop={true}
      onDidDismiss={() => onButtonPressed(undefined)} data-testid="triggerMenu-popup">

      <div className="popover-content2" style = {{marginBottom: "0px"}}>
        {buttons.slice(0,3)}
      </div>
      <div className="popover-content2">
        {buttons.slice(3,buttonLabels.length)}
      </div>

    </IonPopover>
  );
};

export default SelectFromOptionsPopover;
