import { isPlatform } from "@ionic/react";
import React from "react";

export type WaveInfoDisplayElement = {
  label: string,
  value: string,
  unit: string,
  isCursor: boolean,
};

enum Display {
  Hidden = "display-data-hidden",
  MainMobile = "display-data-main",
  FullscreenMobile = "display-data-full",
  MainWeb = "display-data-main-web",
  FullscreenWeb = "display-data-full-web",
}

type Props = {
  hidden: boolean,
  // Determines whether the component appears in the fullscreen mode or the main mode
  isFullscreen: boolean,
  cursorFlag: boolean,
  elements: Array<WaveInfoDisplayElement>,
  color: string,
  onClick?: () => void,
};

const WaveInfoDisplay: React.FC<Props> = ({ hidden, isFullscreen, cursorFlag, elements, color, onClick }) => {

  const isMobile = isPlatform("mobile");

  function displayClassName() {
    if (hidden) {
      return Display.Hidden;
    }
    else if (isMobile && isFullscreen) {
      return Display.FullscreenMobile;
    }
    else if (isMobile && !isFullscreen) {
      return Display.MainMobile;
    }
    else if (!isMobile && isFullscreen) {
      return Display.FullscreenWeb;
    }
    else if (!isMobile && !isFullscreen) {
      return Display.MainWeb;
    }
    else {
      return Display.MainWeb;
    }
  }

  function labelElements() {
    const filteredElements = elements.filter(function (element) {
      return !element.isCursor || cursorFlag;
    });

    return filteredElements.map((element) =>
      <li key={element.label}>
        <b>{element.label}</b>: {element.value} {element.unit}<br/>
      </li>
    );
  }

  return (
    <div className={displayClassName()} style={{backgroundColor: `${color}`}} onClick={onClick}>
      {labelElements()}
    </div>
  );
};

export default WaveInfoDisplay;
