import React, { useRef, useEffect } from 'react';
import Paper from 'paper';
import drawGraph from '../DrawGraph';
import drawCursors, {setCursorFlag} from '../cursors';
import {
	drawSpectrumWave,
	setWindowType,
	setCenter,
	setSpectrumDrawWave,
	setDecibelsDiv,
	setFreqDiv,
	setSpectrumAutoset,
	setSpectrumSaveFlag,
	setFFTSize,
	setChannel1Enabled,
	setChannel2Enabled
} from '../DrawSpectrumWave';
import { isPlatform } from '@ionic/react';

const SpectrumAnalyzerScope = (props: any) => {

	const canvasRef: any = useRef(null);
	const renderFrame: any = useRef(null);

	const animate = () => {
		if(canvasRef.current === null || canvasRef.current.clientWidth === 0) {
			renderFrame.current = requestAnimationFrame(animate);
			return;
		}
		const canvas = canvasRef.current;
		Paper.setup(canvas);

		drawGraph(true);
		drawSpectrumWave({
			changeCenter: props.centerChangeCallback,
			finishAutoset: props.autosetFinishCallback,
			finishSave: props.saveFinishCallback
		});
		drawCursors(props.cursorChangeCallback);

		(Paper.view as any).draw();
	}

	useEffect(() => {
		renderFrame.current = requestAnimationFrame(animate);

		return () => {
			cancelAnimationFrame(renderFrame.current);
		};
	}, []);

	useEffect(() => {
		// If we have a view, fix the scaling on fullscreen toggle
		if(!Paper.view) { return; }
		Paper.view.viewSize = isPlatform("mobile") ?
			new Paper.Size(canvasRef.current.clientWidth, canvasRef.current.clientHeight) :
			new Paper.Size(canvasRef.current.clientWidth*2, canvasRef.current.clientHeight*2);
		Paper.view.emit('resize', {});
	}, [props.isFullscreen]);

	// Shared
	useEffect(() => {
		setSpectrumDrawWave(props.playPauseFlag);
	}, [props.playPauseFlag]);

	useEffect(() => {
		setSpectrumAutoset(props.autoset);
	}, [props.autoset]);

	useEffect(() => {
		setCursorFlag(props.cursorFlag, props.cursorFlag);
	}, [props.cursorFlag]);

	useEffect(() => {
		setSpectrumSaveFlag(props.saveFlag);
	}, [props.saveFlag]);

	// Spectrum Analyzer
	useEffect(() => {
		setDecibelsDiv(props.decibelsDiv);
	}, [props.decibelsDiv]);

	useEffect(() => {
		setFreqDiv(props.freqDiv);
	}, [props.freqDiv]);

	useEffect(() => {
		setWindowType(props.windowType);
	}, [props.windowType]);

	useEffect(() => {
		setCenter(props.center);
	}, [props.center]);

	useEffect(() => {
		setFFTSize(props.fftSize);
	}, [props.fftSize]);

	useEffect(() => {
		setChannel1Enabled(props.channel1Enabled);
	}, [props.channel1Enabled]);

	useEffect(() => {
		setChannel2Enabled(props.channel2Enabled);
	}, [props.channel2Enabled]);

	return <canvas ref={canvasRef} className={props.className} data-paper-resize="true" id="canvas" />;
}

export default SpectrumAnalyzerScope;
