import React, { useRef, useEffect } from 'react';
import Paper from 'paper';
import drawGraph from '../DrawGraph';
import DrawDraggables, { setChannel1EnabledForDraggables, setChannel2EnabledForDraggables } from '../DrawDraggables'
import drawCursors, {setCursorFlag} from '../cursors';
import Channel from "../../enums/Channel";
import TriggerState from "../../enums/TriggerState";
import {
	drawOscopeWave,
	setTriggerState,
	setOscopeDrawWave,
	setChannel1VoltDiv,
	setTimeDiv,
	setOscopeAutoset,
	setOscopeSaveFlag,
	setChannel1Enabled,
	setChannel2Enabled,
	setChannel2VoltDiv,
	setTriggerChannel,
	setYOffsets,
	setTriggers
} from '../DrawOscopeWave';
import { isPlatform } from '@ionic/react';


interface OscilloscopeScopeProperty{
	className: string;
	isFullscreen: boolean;
	pausePlay: boolean;
	voltageDiv: number;
	timeDiv: number;
	autoset: boolean;
	// triggerEnable: boolean;
	cursorEnable: boolean;
	save: boolean;
	triggerState: TriggerState;
	channel1VoltDiv: number;
	channel2VoltDiv: number;
	channel1Enabled: boolean;
	channel2Enabled: boolean;
	// channel1BufferSize: number;
	// channel2BufferSize: number;
	// XAxisDivChangeCallback : (time: number) => void;
	channelFrequencyChangeCallback: (channel: Channel, frequency: number) => void;
	voltageDivChangeCallback: (channel: Channel, voltage: number) => void;
	autosetFinishCallback: () => void;
	saveFinishCallback: () => void;
	cursorChangeCallback: (timeDiff: number, voltDiff: number) => void;
	triggerChannel: Channel;
	changeTimeDiv: (timeDiv: number) => void;
};

/**
 * OScope Display
 * @param  props: any           Properties for OScope // TOOD: make into interface.
 * @return         				Canvas
 */
const OscilloscopeScope = (props: OscilloscopeScopeProperty) => {

	const canvasRef: any = useRef(null);
	const renderFrame: any = useRef(null);

	/**
	 * Draws the frame
	 */
	const animate = () => {
		if(canvasRef.current === null || canvasRef.current.clientWidth === 0) {
			renderFrame.current = requestAnimationFrame(animate);
			return;
		}

		const canvas = canvasRef.current;
		Paper.setup(canvas);

		drawGraph(false);
		DrawDraggables({
			changeTriggers: (timeValue, voltValue) => setTriggers(timeValue, voltValue),
			changeYOffsets: (ch1Offset, ch2Offset) => setYOffsets(ch1Offset, ch2Offset),
		});
		drawOscopeWave({
			changeChannelFrequency: props.channelFrequencyChangeCallback,
			changeChannelVoltDiv: props.voltageDivChangeCallback,
			changeTimeDiv: props.changeTimeDiv,
			finishAutoset: props.autosetFinishCallback,
			finishSave: props.saveFinishCallback
		});
		drawCursors(props.cursorChangeCallback);

		(Paper.view as any).draw();
	}

	/**
	 * Constructors and Destructors
	 */
	useEffect(() => {
		// On Creations
		renderFrame.current = requestAnimationFrame(animate);

		// On Destruction
		return () => {
			cancelAnimationFrame(renderFrame.current);
		};
	}, []);

	/**
	 * Fullscreen Resize Hook
	 * Handles when the screen go into fullscreen
	 */
	useEffect(() => {
		// If we have a view, fix the scaling on fullscreen toggle
		if(!Paper.view) { return; }
		Paper.view.viewSize = isPlatform("mobile") ?
			new Paper.Size(canvasRef.current.clientWidth, canvasRef.current.clientHeight) :
			new Paper.Size(canvasRef.current.clientWidth*2, canvasRef.current.clientHeight*2);
		Paper.view.emit('resize', {});
	}, [props.isFullscreen]);

	// Shared

	/**
	 * onPlayPause change
	 */
	useEffect(() => {
		setOscopeDrawWave(props.pausePlay);
	}, [props.pausePlay]);

	/**
	 * onAutoSet Change
	 */
	useEffect(() => {
		setOscopeAutoset(props.autoset);
	}, [props.autoset]);

	/**
	 * onTriggerFlagChange
	 */
	useEffect(() => {
		setTriggerState(props.triggerState);
	}, [props.triggerState]);

	/**
	 * onCursorFlagChange
	 */
	useEffect(() => {
		setCursorFlag(props.cursorEnable, props.cursorEnable);
	}, [props.cursorEnable]);

	/**
	 * onSavePressed
	 */
	useEffect(() => {
		setOscopeSaveFlag(props.save);
	}, [props.save]);

	/**
	 * onVoltageDivisionChange
	 */
	useEffect(() => {
		setChannel1VoltDiv(props.channel1VoltDiv);
	}, [props.channel1VoltDiv]);

	useEffect(() => {
		setChannel2VoltDiv(props.channel2VoltDiv);
	}, [props.channel2VoltDiv]);

	/**
	 * onTimeDivisionChange
	 */
	useEffect(() => {
		setTimeDiv(props.timeDiv);
	}, [props.timeDiv]);

	useEffect(() => {
		setTriggerChannel(props.triggerChannel);
	}, [props.triggerChannel]);

	/**
	 * onChannel1EnableChange
	 */
	useEffect(() => {
		setChannel1Enabled(props.channel1Enabled);
		setChannel1EnabledForDraggables(props.channel1Enabled);
	}, [props.channel1Enabled]);

	/**
	 * onChannel2EnableChange
	 */
	useEffect(() => {
		setChannel2Enabled(props.channel2Enabled);
		setChannel2EnabledForDraggables(props.channel2Enabled);
	}, [props.channel2Enabled]);

	return <canvas ref={canvasRef} className={props.className} data-paper-resize="true" id="oscilloscope" />
}

export default OscilloscopeScope;
