import React, {useState} from 'react';
import { isPlatform, IonContent, IonPage, IonButton} from '@ionic/react';

import './Pages.css';
import SpectrumAnalyzerScope from '../components/scopes/SpectrumAnalyzerScope';
import WakeLock from '../components/WakeLock';
import PageHeader from '../components/PageHeader';
import FullscreenDisplayButton from '../buttons/FullscreenDisplayButton';
import FullscreenExitButton from '../buttons/FullscreenExitButton';
import WaveInfoDisplay, { WaveInfoDisplayElement } from '../components/WaveInfoDisplay';
import SelectFromOptionsPopover from '../components/SelectFromOptionsPopover';
import KeyboardInputPopover from '../components/KeyboardInputPopover';
import { clamp } from '../utils/MathUtils';
import { WindowFunction } from '../enums/WindowFunction';
import FFTSize from "../enums/FFTSize";
import { serialConnection } from '../components/Serial';

const SpectrumAnalyzer: React.FC = () => {
  const name = "Spectrum Analyzer";
  const POINTS_DIV = 20;
  const NUM_FREQ_DIVS = 10;
  const NUM_DECIBEL_DIVS = 8;
  const SAMPLE_RATE = 44100;
  const NYQUIST_FREQ = SAMPLE_RATE / 2;
  const DECIBELS_DIV = 25.0;
  const minCenter = 0;
  const maxCenter = 20000;
  const WindowTypeOptions = [WindowFunction.eRectangle, WindowFunction.eHanning, WindowFunction.eGaussian, WindowFunction.eHamming, WindowFunction.eKaiser, WindowFunction.eFlatTop];
  const FFTSizeOptions = [FFTSize.e128, FFTSize.e256, FFTSize.e512, FFTSize.e1024, FFTSize.e2048, FFTSize.e4096];

  // TODO: Set this to false, when changing Buffer size on hardware board.
  // Contact @Root3287 for more information. <3
  const [playing, setPlaying] = useState(true);

  const [channel1Flag, setChannel1Flag] = useState(true);
  const [channel2Flag, setChannel2Flag] = useState(false);
  const [fullscreenFlag, setFullscreenFlag] = useState(true);
  const [displayFlag, setDisplayFlag] = useState(true);
  const [freqCount, setFreqCount] = useState(1);
  const [fftSize, setFFTSize] = useState(4096);
  const [freqDiv, setFreqDiv] = useState(POINTS_DIV * (SAMPLE_RATE / fftSize));
  const [center, setCenter] = useState(freqDiv * 5);
  const [windowType, setWindowType] = useState(WindowFunction.eRectangle);
  const [cursorFlag, setCursorFlag] = useState(false);
  const [autoset, setAutoset] = useState(false);
  const [freqDiff, setFreqDiff] = useState(0);
  const [voltDiff, setVoltDiff] = useState(0);
  const [saveFlag, setSaveFlag] = useState(false);

  const [fftSizePopoverHidden, setFFTSizePopoverHidden] = useState(true);
  const [centerPopoverHidden, setCenterPopoverHidden] = useState(true);
  const [windowPopoverHidden, setwindowPopoverHidden] = useState(true);

  function changeCursorDiff(freqDiff: number, voltDiff: number){
    setFreqDiff(freqDiff);
    setVoltDiff(voltDiff);
  }

  function changeCenter(center : number) {
    const newCenter = clamp(minCenter, center, maxCenter);
    setCenter(newCenter);
  }

  function changeFreqInc(){
    if(NYQUIST_FREQ <= ( freqDiv * freqCount * NUM_FREQ_DIVS) ){ return; }
    setFreqCount((prev) => prev+1)
  }

  function changeFreqDec(){
    if(freqCount <= 1){ return; }
    setFreqCount((prev) => prev-1)
  }

  function changeFreqDiv(freqDiv : number) {
    setFreqCount(freqDiv)
  }

  function togglePlay(){
    setPlaying(!playing);
  }

  function changeDisplayFlag(){
    setDisplayFlag(!displayFlag);
  }

  function changeFullscreenFlag(){
    setFullscreenFlag(!fullscreenFlag);
  }

  function changeCursorFlag(){
    setCursorFlag(!cursorFlag)
  }

  function toggleSaveButton() {
    // Don't allow toggling off via button.
    setSaveFlag(true);
  }

  function saveFinish() {
    setSaveFlag(false);
  }

  function popoverCenterSet(value: number | undefined) {
    setCenterPopoverHidden(true);
    if (value === undefined) return;
    setCenter(clamp(value, minCenter, maxCenter));
  }

  function toggleAutosetButton() {
    // Don't allow toggling off via button.
    setAutoset(true);
  }

  function autosetFinish() {
    setAutoset(false);
  }

  // Number given in this case is the number of datapoints for the FFT (powers of 2).
  function popoverFFTSizeMenuSet(value: string | undefined) {
    setFFTSizePopoverHidden(true);
    if (value === undefined) return;
    const freqPerPoint = SAMPLE_RATE / +value;
    const freqDiv = POINTS_DIV * freqPerPoint;
    setFreqDiv(freqDiv);
    setCenter(freqDiv * (NUM_FREQ_DIVS / 2));
    setFFTSize(+value);
  }

  // Number given in this case (for now and should be temporary) is a string. Ex: 'rectangle'.
  function popoverWindowSet(value: string | undefined) {
    setwindowPopoverHidden(true);
    if (value === undefined) return;
    setWindowType(value as WindowFunction);
  }

  function calculateDecibels() {
    return (DECIBELS_DIV*NUM_DECIBEL_DIVS*voltDiff).toFixed(1)
  }
  function calculateFrequency(){
    return (freqCount*freqDiv*NUM_FREQ_DIVS*freqDiff).toFixed(3)
  }
  function calculateFrequencyDivision(){
    return (freqCount*freqDiv).toFixed(3)
  }
  function calculateDecibelsDivision(){
    return DECIBELS_DIV.toFixed(1)
  }

  function channel1Info() {
    const elements: WaveInfoDisplayElement[] = [
      { label: 'Freq Division', value: calculateFrequencyDivision(), unit: 'Hz', isCursor: false},
      { label: 'Decibels Division', value: calculateDecibelsDivision(), unit: 'dB', isCursor: false},
      { label: 'Center', value: center.toFixed(3), unit: 'Hz', isCursor: false},
      { label: 'Window', value: windowType, unit: '', isCursor: false},
      { label: 'FFT Size', value: fftSize.toString(), unit: '', isCursor: false},
      { label: 'Decibels', value: calculateDecibels(), unit: 'dB', isCursor: true},
      { label: 'Frequency', value: calculateFrequency(), unit: 'Hz', isCursor: true},
    ];
    return elements;
  }

  function toggleChannel1Button() {
    serialConnection.setAnalogChannelEnable(!channel1Flag, channel2Flag);
    setChannel1Flag(!channel1Flag);
  }

  function toggleChannel2Button() {
    serialConnection.setAnalogChannelEnable(channel1Flag, !channel2Flag);
    setChannel2Flag(!channel2Flag);
  }

  return (
    <IonPage>
      <PageHeader
        name={name}
        hidden={!fullscreenFlag}
        isConnectHidden={false}
        onFullscreenClick={changeFullscreenFlag}
        tutorialPath={"SpectrumAnalyzer"}
      />

      <IonContent fullscreen scrollY={false} color="secondary">
      <div className="full-screen">

        <FullscreenExitButton hidden={fullscreenFlag} onClick={changeFullscreenFlag}/>
        <FullscreenDisplayButton hidden={fullscreenFlag} onClick={changeDisplayFlag}/>
        <div className={isPlatform("mobile") ? "display-div-fullscreen-mobile" : "display-div-fullscreen"}>
            <WaveInfoDisplay
              hidden={displayFlag || fullscreenFlag}
              isFullscreen={true}
              cursorFlag={cursorFlag}
              elements={channel1Info()}
              color={"#D00000"}
            />
        </div>

        {/* Makes it so the screen doesn't turn off when on the oscope page */}
        <WakeLock enabled={true} />

        {/* The graph element for the spectrum analyzer */}
        <div className={isPlatform("mobile") ? (fullscreenFlag ? "oscilloscope-div" : "oscilloscope-div-full") :
                                                                     (fullscreenFlag ? "oscilloscope-div-web" : "oscilloscope-div-full-web")}>
        <SpectrumAnalyzerScope
          className="graph"
          isFullscreen={fullscreenFlag}
          playPauseFlag = {playing}
          decibelsDiv = {DECIBELS_DIV}
          freqDiv = {freqCount}
          cursorChangeCallback = {changeCursorDiff}
          XAxisDivChangeCallback = {changeFreqDiv}
          centerChangeCallback = {changeCenter}
          fftSize = {fftSize}
          autoset = {autoset}
          autosetFinishCallback = {autosetFinish}
          cursorFlag = {cursorFlag}
          saveFlag = {saveFlag}
          saveFinishCallback = {saveFinish}
          windowType = {windowType}
          center = {center}
          channel1Enabled = {channel1Flag}
          channel2Enabled = {channel2Flag}
        />
        <div className={fullscreenFlag ? "under-graph-div" : "under-graph-div-full"}>
            <div>
              <div className="under-graph-background">
                <IonButton className="graph-button" mode="ios" onClick = {() => toggleChannel1Button()} fill={channel1Flag ? "solid" : "clear"} color={channel1Flag ? "primary" : "tertiary"} hidden={!fullscreenFlag} data-testid="channel-button">
                  <div>
                    Channel 1
                  </div>
                </IonButton>
                <IonButton className="graph-button" mode="ios" onClick = {() => toggleChannel2Button()} fill={channel2Flag ? "solid" : "clear"} color={channel2Flag ? "channel2" : "tertiary"} hidden={!fullscreenFlag} data-testid="channel-button">
                  <div>
                    Channel 2
                  </div>
                </IonButton>
              </div>
            </div>
          </div>
        </div>

        {/* The buttons on the right hand side of the graph */}
        <div className={isPlatform("mobile") ? (fullscreenFlag ? "side-data" : "side-data-hidden") :
                                                                     (fullscreenFlag ? "side-data-web" : "side-data-hidden")}>
          <div className="first-row-div"> {/* First row of UI buttons */}
            <IonButton className="utility-buttons" mode="ios" onClick = {() => toggleAutosetButton()} color={autoset ? "primary" : "light"} data-testid="autoset-button">
                <div>
                  Auto
                </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick={() => setFFTSizePopoverHidden(false)} color="tertiary" data-testid="FFT-size-button">
              <div>
                FFT Size
              </div>
            </IonButton>
            <IonButton className="utility-buttons" mode="ios"  onClick = {() => changeCursorFlag()} color={cursorFlag ? "primary" : "light"} data-testid="cursor-button">
              <div>
                Cursors
              </div>
            </IonButton>
          </div>

          <div className="second-row-div"> {/* Second row of UI buttons */}
          <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => changeFreqDec()} color="tertiary" data-testid="time-div-neg-button">
              <div>
                Freq/Div
                <div>
                  -{freqDiv.toFixed(3)}Hz
                </div>
              </div>
            </IonButton>
            <IonButton id = "pause-play-button" className="pause-play-button" mode="ios" onClick = {() => togglePlay()} color={playing ? "primary" : "tertiary"} data-testid="pause-play-button-sa">
              <div>
                <img className="pause-play-img" src={process.env.PUBLIC_URL + (!playing ? "/assets/pause.png" : "/assets/playwhite.png")} alt="" ></img>
                <div>{ playing ? "Playing" : "Paused" } </div>
              </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => changeFreqInc()} color="tertiary" data-testid="time-div-pos-button">
              <div>
                Freq/Div
                <div>
                  +{freqDiv.toFixed(3)}Hz
                </div>
              </div>
            </IonButton>
          </div>

          <div className="third-row-div"> {/* Third row of UI buttons */}
            <IonButton className="utility-buttons" mode="ios" onClick = {() => toggleSaveButton()} color={saveFlag ? "primary" : "light"} data-testid="save-button">
                <div>
                  Save
                </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick={() => setCenterPopoverHidden(false)}  color="tertiary" data-testid="center-button">
              <div>
                Center
              </div>
            </IonButton>
            <IonButton className="utility-buttons" mode="ios" onClick={() => setwindowPopoverHidden(false)} color="light" data-testid="window-button">
              <div>
                Window
              </div>
            </IonButton>
          </div>
          <div className="display-div">
            <WaveInfoDisplay
              hidden={!fullscreenFlag}
              isFullscreen={false}
              cursorFlag={cursorFlag}
              elements={channel1Info()}
              color={"#D00000"}
            />
          </div>
        </div>
      </div>

      {/* Center Popover */}
      <KeyboardInputPopover hidden={centerPopoverHidden} minInput={minCenter} maxInput={maxCenter} inputUnits="Hz" onClose={popoverCenterSet}/>

      {/* FFT Size Menu Popover */}
      <SelectFromOptionsPopover hidden={fftSizePopoverHidden} buttonLabels={FFTSizeOptions} onButtonPressed={popoverFFTSizeMenuSet}/>

      {/* Window Menu Popover */}
      <SelectFromOptionsPopover hidden={windowPopoverHidden} buttonLabels={WindowTypeOptions} onButtonPressed={popoverWindowSet}/>
      </IonContent>
    </IonPage>
  );
};

export default SpectrumAnalyzer;
