import { IonButton, IonInput, IonPopover, isPlatform } from "@ionic/react";
import React, { useRef, useState } from "react";
import '../pages/Pages.css';

type Props = {
  hidden: boolean,
  minInput: number,
  maxInput: number,
  inputUnits: string,
  onClose: (value: number | undefined) => void,
};

const KeyboardInputPopover: React.FC<Props> = ({ hidden, minInput, maxInput, inputUnits, onClose }) => {

  const isMobile = isPlatform("ios") || isPlatform("android");
  const [currentInput, setCurrentInput] = useState(minInput);

  // Setting focus of the input popover
  const input = useRef<HTMLIonInputElement>(null!);
  function inputFocus() {
    input.current.setFocus();
  }

  function keyUpHandler(event: React.KeyboardEvent<HTMLIonInputElement>) {
    if (event.key !== "Enter") return;
    onClose(currentInput);
  }
  
  return (
    
    <IonPopover
      isOpen={!hidden}
      className={isMobile ? "input-popover" : "input-popover-web"}
      mode="ios"
      showBackdrop={true}
      onDidPresent={() => inputFocus()}
      onDidDismiss={() => onClose(undefined)} data-testid="center-popup">
      <div className="popover-content">
        <IonInput ref={input} class="input-popover-text" type="number" inputmode="numeric" placeholder={minInput + " to " + maxInput + " " + inputUnits}
          onIonChange={e => inputUnits.toUpperCase() !== "V" ? setCurrentInput(parseInt(e.detail.value!, 10)): setCurrentInput(parseFloat(parseFloat(e.detail.value!).toFixed(2)))}
          onKeyUp={e => keyUpHandler(e)}
        ></IonInput>
        <IonButton
          onClick={() => onClose(currentInput)}>
          CONFIRM
        </IonButton>
      </div>
    </IonPopover>
  );
};

export default KeyboardInputPopover;
