function getOperatingSystem() {
  var userAgent = window.navigator.userAgent,
      platform = window.navigator.platform,
      macosPlatforms = ['Macintosh', 'MacIntel', 'MacPPC', 'Mac68K'],
      windowsPlatforms = ['Win32', 'Win64', 'Windows', 'WinCE'];

  if (macosPlatforms.indexOf(platform) !== -1) {
    return 'OS';
  } else if (windowsPlatforms.indexOf(platform) !== -1) {
    return 'Wnd';
  } else {
    return '';
  }
}
 
function getBitFromUint8(uint8Value, channel) {
  // Check if the channel is within the valid range (1 to 8)
  if (channel < 1 || channel > 8) {
      throw new Error("Channel number must be between 1 and 8.");
  }

  // Calculate the mask to extract the bit corresponding to the channel
  const mask = 1 << (channel - 1);

  // Use bitwise AND operator to extract the bit
  const bit = (uint8Value & mask) !== 0 ? 1 : -1;

  return bit;
}

  function convertLogicToFloat(uint8Value, channel) {
  if(channel >= 1 && channel <= 8) {
    return getBitFromUint8(uint8Value, channel);
  } else {
    throw new Error("Invalid channel number.");
  }
}

  function findMaxVoltage(array) {
  let maxPoint = .01;
  for(let i = 0; i < array.length; i++){
    let point = Math.abs(array[i]);
    if (point > maxPoint) {
      maxPoint = point;
    }
  }
  return maxPoint;
}

  function findMinVoltage(array) {
  let minPoint = 1;
  for(let i = 0; i < array.length; i++){
    let point = Math.abs(array[i]);
    if (point < minPoint) {
      minPoint = point;
    }
  }
  return minPoint;
}

function findTrigger(array, triggerFlag, voltDiff, voltageDiv, voltageMultiplierConstant) {
  let triggerPoint = null;
  let triggerVoltage = (voltDiff*voltageDiv)/voltageMultiplierConstant;
  for(let i = Math.floor(array.length/2); i < array.length-1; i++){
    let point1 = array[i];
    let point2 = array[i+1];
    //Rising Edge
    if(triggerFlag === true){
      if(point1 <= triggerVoltage){
        if(point2 > triggerVoltage){
          triggerPoint = i;
          break;
        }
      }
    } else {
      //Falling Edge 
      if(point1 >= triggerVoltage){
        if(point2 < triggerVoltage){
          triggerPoint = i;
          break;
        }
      }
    }
  }
  return triggerPoint;
}

  function findFrequency(array, sampleRate) {
  let crossCount = 0;
  let firstIndex = -1;
  let lastIndex = -1;
  for(let i = 0; i < array.length - 1; i++){
    let point1 = array[i];
    let point2 = array[i+1];
    if (point1 === 0 || (point1 < 0 && point2 > 0) || (point1 > 0 && point2 < 0)) {
      firstIndex = (!crossCount) ? i : firstIndex
      lastIndex = i;
      crossCount++;
    }
  }
  let frequency = (firstIndex === -1) ? 0 : ( sampleRate * .5 * (crossCount - 1) / (lastIndex - firstIndex) ); 
  return frequency;
}


export { getBitFromUint8, convertLogicToFloat, findMaxVoltage, findMinVoltage, findTrigger, findFrequency, getOperatingSystem };