import { IonButton } from "@ionic/react";
import './Buttons.css';

type Props = {
  hidden: boolean,
  onClick: () => void
};

/**
 * A button to bring the canvas to the fullscreen mode
 * @param  boolean options.hidden               If true, the fullscreen button would be hidden.
 * @param  function(): void options.onClick     A callback function when clicked 
 * @return {[type]}                             Renderable
 */
const FullscreenButton: React.FC<Props> = ({ hidden, onClick }) => {

  return (
    <IonButton className="flscrn-button-graph-small"
               onClick = {() => onClick()}           
               mode="ios" 
               fill="clear"
               hidden={hidden}>
      <img className="fullscreen-img" src={process.env.PUBLIC_URL + "/assets/fullscreenwhite.png"} alt=""></img>
    </IonButton>
    
  );
};

export default FullscreenButton;
