import { Axis } from "../enums/Axis";
import { clamp } from "../utils/MathUtils";
import Paper from "paper";

export class Draggable {
    axis: Axis;
    basePath: any;
    selecting: boolean | null;
    pos: number = 0.5;
    // How many pixels long (from longest side to top) is the Draggable
    length: number = 10;
  
    constructor(axis: Axis) {
  
      this.axis = axis;
      this.selecting = false;
    }
    getY() { return this.basePath.position.y; }
    getSelected() { return this.selecting; }
  
    setVisibility(enabled: boolean) { 
      if (!this.basePath) return;
      this.basePath.visible = enabled; 
    }
  
    setPath (color = 'black', position = 0.5) { 
      this.basePath = new Paper.Path({
        segments: [[0, 0], [this.length, this.length], [this.length*2, 0]],
        fillColor: color,
        selected: false,
        closed: true,
        rotation: this.axis === Axis.eHorizontal ? 0 : -90,
      });
      this.setPosition(position);
    }
  
    setPosition(position: number) { 
      // position should a value from 0-1
      if (position > 1 || 0 > position) return;
      if (!this.basePath) return;
      this.pos = position;
      switch (this.axis) {
        case (Axis.eHorizontal):
          this.basePath.position.x = Paper.view.bounds.width * this.pos;
          this.basePath.position.y = this.length/2;
          break;
        case (Axis.eVertical):
          this.basePath.position.x = this.length/2;
          this.basePath.position.y = Paper.view.bounds.height * (1 - this.pos);
          break;
      }
    }
    
    mousedown(event: any) {
      const hitOptions = {
        stroke: true,
        fill: true,
        tolerance: 50,
      }
      
      const hitDetected = this.basePath.hitTest(event.point, hitOptions);
      this.selecting = hitDetected && hitDetected.item;
    }
  
    mousedrag(event: any) {
      if(!this.selecting) return;
      switch (this.axis) {
        case (Axis.eHorizontal):
          this.pos = clamp(event.point.x / Paper.view.bounds.width, 0.01, 0.99);
          this.basePath.position.x = Paper.view.bounds.width * this.pos;
          break;
        case (Axis.eVertical):
          this.pos = 1 - clamp(event.point.y / Paper.view.bounds.height, 0.01, 0.99);
          this.basePath.position.y = Paper.view.bounds.height * (1 - this.pos);
          break;
      }
      return this.pos;
    }
  
    mouseup(event: any) {
      this.selecting = false;
    }
  
    resize(event: any) {
      this.setPosition(this.pos);
    }
  }