/**
 * Get the mulipliser of the larger freq w.r.t. smaller or 0 if not divisible.
 *
 * This is done by calculating
 *   max(freqOne,freqTwo)/min(freqOne,freqTwo)
 *   
 * If the freqency is a multiple of one another, then this function should return zero.
 * 
 * @param  number   freqOne: number        The sample value of the first frequency.
 * @param  number   freqTwo: number        The sample value of the second frequency.
 * @return number   Returns the multipler;
 */
export function getSyncMultiplier(freqOne: number, freqTwo: number): number {
  let remainder = Math.max(freqOne, freqTwo) % Math.min(freqOne, freqTwo);
  let multiplier = Math.max(freqOne, freqTwo) / Math.min(freqOne, freqTwo);
  return (remainder == 0) ? remainder : multiplier;
}
