import { IonContent, IonPage, IonImg} from '@ionic/react';
import PageHeader from '../components/PageHeader';
import './Pages.css';
import React, { useEffect, useRef } from "react";


  const Tutorial: React.FC = () => {
  const name = "Tutorial";
  const FunctionGeneratorRef = useRef<HTMLDivElement>(null);
  const OscopeRef = useRef<HTMLDivElement>(null);
  const AMFMRef = useRef<HTMLDivElement>(null);
  const SpectrumAnalyzerRef = useRef<HTMLDivElement>(null);
  const LogicAnalyzerRef = useRef<HTMLDivElement>(null);
  const referencePage = window.location.search.replace("?", ""); // returns query string url

  // Essentially this would be our constant time switch statement.
  // Use to scroll to a certian page for the tutorial.
  const pageMap : {[index: string]:any} = {
    "FunctionGenerator": FunctionGeneratorRef,
    "OScope": OscopeRef,
    "SpectrumAnalyzer": SpectrumAnalyzerRef,
    "AMFM": AMFMRef,
    "LogicAnalyzer" : LogicAnalyzerRef
  }

  function scroll(pageRef: any){
    if(!pageRef || !pageRef.current) return;
    pageRef.current.scrollIntoView({
      behaivor: 'smooth',
      block: 'start',
      inline: 'start',
    });
  }

  useEffect(() => {
    setTimeout(() => {
      scroll(pageMap[referencePage]);
    }, 500);
  }, [referencePage]);


  return (
    <IonPage>
      <PageHeader
          name={name}
          hidden={false}
          isConnectHidden={true}
          onFullscreenClick={()=> {}}
      />
      <IonContent fullscreen scrollY={true} color="secondary">
        <div className='tutorial-page'>
          <div className="main-div">
            <div className="intro-div">
              <p> This page serves as a tutorial for what all the buttons on the Function Generator and Oscilloscope do. First will be an
                  image of the Function Generator with what all the buttons on the UI do. Following that, there will be a picture of the Oscilloscope with information
                  on what the buttons do. We hope it's of help! <br/><br/>
                  If you would like to learn more about the Husker Scope board (the compatible hardware board) to use this app to its fullest extent, please visit  <a href="http://www.huskerscope.com">www.huskerscope.com</a>
              </p>
            </div>
            <div ref={FunctionGeneratorRef} className= "fg-tutorial-instructions">
              <h1>Function Generator</h1>
              <div className='fg-tutorial-img-div'>
                <IonImg className="fg-tutorial-img" src={process.env.PUBLIC_URL + "/assets/function_generator_tutorial.png"} />
              </div>

              <ol>
                <li>These buttons are to select which channel the user wants to edit.</li>
                <li>This button serves the purpose of displaying the frequency of the channel and if it is pressed, a popup is displayed that allows for an exact
                    frequency to be entered using the keyboard.</li>
                <li>This button serves the purpose of displaying the amplitude of the channel and if it is pressed, a popup is displayed that allows for an exact
                    amplitude to be entered using the keyboard.</li>
                <li>This button serves the purpose of displaying the phase of the channel and if it is pressed, a popup is displayed that allows for an exact
                    phase to be entered using the keyboard. <br /> Note: The sliders underneath the previous 3 buttons are for changing the values of frequency,
                    amplitude, and phase respectively.</li>
                <li>The four waveform buttons are used for setting the waveform for the currently selected channel.</li>
                <li>These two buttons are for playing and pause the output on the respective channels.</li>
              </ol>

              <h1 ref={OscopeRef}>
                Oscilloscope
              </h1>
              <div className='os-tutorial-img-div'>
                <IonImg className="os-tutorial-img" src={process.env.PUBLIC_URL + "/assets/dual_oscope.png"} />
              </div>

              <ol>
                <li>This is the oscilloscope graph, which is where the wave is displayed.</li>
                <li>The small triangles in black on the top and left of the graph are the oscilloscope's triggers.</li>
                <li>The red half-circles on the sides of the graph are the oscilloscope's cursors.</li>
                <li>The red and blue triangles allow you to drag the respective waves in the oscilloscope.</li>
                <li>This is a data display which is used for displaying the frequency, time division, volt division, and if the cursors are enabled for Channel 1. It also
                    displays the voltage and time measures.</li>
                <li>This is a data display which is used for displaying the frequency, time division, volt division, and if the cursors are enabled for Channel 2. it also
                    displays the voltage and time measures.</li>
                <li>This button is used for autosetting the graph.</li>
                <li>This button and the button below the run/pause button are used for increasing and decreasing the voltage division. A menu will pop up which will allow the user to change voltage division specific to the wave.</li>
                <li>This button enables and disables the cursors on the graph. If the button is red, the cursors are enabled. If the button is white, the cursors are disabled.</li>
                <li>This button and the button to the right of the run/pause button are used for increasing and decreasing the time division of the signal.</li>
                <li>This button plays or pauses the incoming signal generation from the Husker Scope board. If the button is red, the graph will update. If it is white, the graph will be paused.</li>
                <li>This button displays a trigger menu that has the options for changing between rising and falling edge and single trigger.</li>
                <li>This button allows for the configuration of the Husker Scope board scaler, a single channel sample rate, a single channel sample time, a dual channel sample rate, and a dual channel sample time.</li>
                <li>This is the connect button which can be used to connect to the Husker Scope board either through a serial or bluetooth connection.</li>
                <li>This button allows the user to enable waves on Channel 1 and Channel 2.</li>
                <li>This button allows the user to enable a trigger on either Channel 1 or Channel 2.</li>
                <li>This button changes the graph to fullscreen. After the graph is in fullscreen, there is a button in the same location that disables the fullscreen.<br />
                    Note: When the graph is in fullscreen, the button below the fullscreen button enables and disables the data display.</li>
                <li>Save Button: In Progress</li>
              </ol>

              <h1 ref={AMFMRef}>AM-FM</h1>

              <div className='amfm-tutorial-img-div'>
                <IonImg className="amfm-tutorial-img" src={process.env.PUBLIC_URL + "/assets/am.png"} />
              </div>

              <ol>
                <li>These buttons are to select which channel the user wants to edit.</li>
                <li>This button defines the carrier frequency for the current channel.</li> {/* Carrier Frequency Here */}
                <li>This buttons defines the message frequency for the current channel.</li> {/* Message Frequency Here */}
                <li>This button serves the purpose of displaying the amplitude of the channel and if it is pressed, a popup is displayed that allows for an exact
                    amplitude to be entered using the keyboard.</li>
                    <li>This button switches the modulation mode from amplitude modulation to frequency modulation.</li> {/* AM button Here */}
                <li>These two buttons are for playing and pause the output on the respective channels.</li>

              </ol>

            <h1 ref={SpectrumAnalyzerRef}>Spectrum Analyzer</h1>
            <div>
              <div className= 'sa-tutorial-img-div'>
                <IonImg className="sa-tutorial-img" src={process.env.PUBLIC_URL + "/assets/sadual.png"} />
              </div>
              <ol >
                <li>This is the spectrum analyzer graph, which is where the wave is displayed.</li>
                <li>The red half-circles on the sides of the graph are the spectrum analyzer's cursors. </li>
                <li>This is a data display which is used for displaying the frequency, decibels division, volt division, and if the cursors are enabled. It also
                    displays the frequency and the decibels. </li>
                <li>This button can be used to change the size of the FFT.</li>
                <li>This button enables and disables the cursors on the graph. If the button is red, the cursors are enabled. If the button is white, the cursors are disabled.</li>
                <li>This button and the button to the right of the run/pause button are used for decreasing and increasing the frequency division.</li>
                <li>This is the run/pause button. If the button is red, the graph will update. If it is white, the graph will be paused.</li>
                <li>This button is used for autosetting the graph.</li>
                <li>This button is used to set the center frequency of the graph.</li>
                <li>This button saves the data into a .csv file.</li>
                <li>This button displays a window menu to select different window functions. </li>
                <li>This button changes the graph to fullscreen. After the graph is in fullscreen, there is a button in the same location that disables the fullscreen. <br />
                    Note: When the graph is in fullscreen, the button below the fullscreen button enables and disables the data display.</li>
                <li>This is the connect button which can be used to connect to the Husker Scope board either through a serial or bluetooth connection.</li>
                <li>This button allows the user to enable waves on Channel 1 and Channel 2.</li>
              </ol>
</div>
              <h1 ref={LogicAnalyzerRef}>Logic Analyzer</h1>
            <div>
              <div className= 'sa-tutorial-img-div'>
                <IonImg className="sa-tutorial-img" src={process.env.PUBLIC_URL + "/assets/2025la_2.png"} />
              </div>
              <ol >
                <li>This is the logic analyzer graph, which is where the waves for each channel are displayed. When the waves are hovered over (PC) or clicked on (Mobile), timing information is displayed.</li>
                <li>This is the time bar that displays what portion of the current sample you are currenty viewing.</li>
                <li>These buttons are used to control zoom functionality within the graph. These will change the time scales as you zoom. Scroll zoom is also avaliable for compatible devices.</li>
                <li>These buttons are used to change the viewing position of the graph. Scroll position change is also avaliable for compatible devices.</li>
                <li>This is the record button which will start recording data being sent by the Husker Scope board after it is clicked. The data will then start to populate the graph.</li>
                <li>This button controls the cursor view which will appear on the graph and can be adjusted after it is clicked. </li>
                <li>This button brings up the trigger menu when pressed. The options to select are the different trigger modes and the specific channel in which the
                  trigger will be applied.</li>
                <li>This button brings up the decoding menu when pressed. The options to select are the decoding modes and the specific channel the decoding will be applied to.</li>
                <li>This is the information box that displays the number of samples, sample rate, and current time division. This box will update depending on zoom level and starting conditions. When it is
                   clicked, the user can adjust the number of samples displayed and the frequency. This box will also display the current trigger selected and which channel the trigger is being applied to.
                   Additionally, it will specify which decoding mode is selected and which channel the decoding is being applied to.</li>
                <li>This is the connect button which can be used to connect to the Husker Scope board either through a serial or bluetooth connection.</li>
                <li>These are the channel labels which can be clicked on and re-named however the user finds it useful. When the channel names are changed, the trigger menu, decoding menu, and information
                  box will also reflect this change.</li>
                <li>This is the decoding channel which will appear only when a decoding mode is selected from the decoding menu. After a mode and channel is selected, the current mode and signal for the
                  selected channel will be shown.</li>
                <li>This button changes the graph to fullscreen. After the graph is in fullscreen, there is a button in the same location that disables the fullscreen. <br />
                    Note: When the graph is in fullscreen, the button below the fullscreen button enables and disables the data display.</li>
              </ol>



              </div>
            </div>
          </div>
        </div>
      </IonContent>
    </IonPage>
  );
};

export default Tutorial;
