import { IonButton } from "@ionic/react";
import { useEffect, useState } from "react";
import { serialConnection } from "../components/Serial";

type Props = {
  hidden: boolean,
  onError?: (error: any) => void,
};

const ConnectButton: React.FC<Props> = (props: Props) => {
  const [isConnected, setIsConnected] = useState(serialConnection.isConnected);

  async function onClick() {
    if (serialConnection.isConnected) {
      await serialConnection.disconnect();
      setIsConnected(false);
    } else {
      const connected = await serialConnection.connect();
      setIsConnected(connected);
    }
  }

  useEffect(()=>{
    setIsConnected(serialConnection.isConnected);
  }, [serialConnection.isConnected])

  return (
    <IonButton
              mode="ios"
              fill="clear"
              onClick = {() => onClick()}
              hidden={props.hidden}>
      {isConnected ? "Disconnect" : "Connect" }
    </IonButton>
  );
};

export default ConnectButton;
