import { IonContent, IonPage, IonImg} from '@ionic/react';
import PageHeader from '../components/PageHeader';
import './Pages.css';

const About: React.FC = () => {
  const name = "About";

  return (
    <IonPage>
      <PageHeader 
          name={name} 
          hidden={false} 
          isConnectHidden={true}
          onFullscreenClick={()=> {}}
      />
      <IonContent fullscreen scrollY={true} color="secondary">
        <div className="content">
          <div className="overview">Project Overview</div>
          <div className="project-vision">Project Vision</div>
          <div className="project-justification">Project Justification</div>
        </div>
        <div className="content">
          <div className="overview-text">Husker Scope is an iOS, Android, and Web application that serves as a dual channel function generator, a dual channel oscilloscope, a dual channel AM/FM frequency generator, a dual channel spectrum analyzer, and an eight channel logic analyzer. The dual channel function generator is able to output sine, square, sawtooth, and triangle waveforms with a range of 20 to 20,000 Hz. 
            The phase, amplitude, and frequency are able to be adjusted within the application. Each of the apps other components have different functionalities that can be configured at the users discretion.</div>
          <div className="outer">
            <div className="project-vision-text">To provide a free and cross-platform application containing a function generator and oscilloscope that will be available to UNL students and Engineering students across the globe.</div>
            <IonImg slot="end" class="logo-about" src={process.env.PUBLIC_URL + "/assets/Husker_Scope_Logo_rounded_corners.png"}></IonImg>
          </div>
          <div className="project-justification-text">There are a variety of function generators, oscilloscopes, and logic analyzers on both the Apple App store and Google Play store, but most of those applications need to be purchased and Husker Scope is a one stop shop for all function generator, oscilloscope, and logic analyzer needs on both the Apple App store and Google Play store. 
            Additionally, most applications require extra hardware to be purchased for proper functionality, but the Husker Scope oscilloscope and spectrum analyzer will function through the use of a standard 3.5mm audio jack.</div>        
        </div>
        <div className="link-text"> 
          More information about the app and project can be found at <a href="https://www.huskerscope.com" target="_blank" rel="noreferrer">huskerscope.com</a>
        </div>
      </IonContent>
    </IonPage>
  );
};

export default About;
