import React, { useEffect } from 'react';
import { Insomnia } from '@awesome-cordova-plugins/insomnia';

interface WakeLockProps {
	enabled: boolean;
}

/**
 * WakeLock
 *
 * This components allow the display to stay on while inactive
 * 
 * @param  WakeLockProps props: WakeLockProps Properties for wake lock
 * @return null        
 */
const WakeLock = (props: WakeLockProps) => {

	useEffect(() => {
		if(!props.enabled) { return; }
		// Wake-lock on
		Insomnia.keepAwake();

		// Disable wakelock when destroyed
		return () => {
			Insomnia.allowSleepAgain();
		};
	}, [props.enabled]);

	return null;
}

export default WakeLock;
