/*
This file is used to display wave on the left side of the 
screen on the spectrum page. This is done with the 
use of paperJS and AudioContext. We will look for the 
access to the users microphone, then for each (1/sampleRate) 
seconds we will pull in the current audio value. Theses vales 
are place in a buffer witch are then put on the graph to show 
the current value of buffer.
*/

import Paper from "paper";
import { setupWaveDataPopulation } from "./WaveData";
import { SpectrumChannelWave } from "./SpectrumChannelWave";
import { WindowFunction } from "../enums/WindowFunction";

let fillDataArrayInterval: any;

// Use Effects
let windowType: WindowFunction;
let center: number;
let autoset: boolean;
let decibelsDiv: number;
let freqDiv: number;
let saveFlag: boolean;
let fftSize: number;
let channel1 = new SpectrumChannelWave(true, '#D00000');
let channel2 = new SpectrumChannelWave(false, '#4169E1');
export const setSpectrumDrawWave = (val: boolean) => {channel1.setDrawing(val); channel2.setDrawing(val) }
export const setDecibelsDiv = (val: number) => decibelsDiv = val;
export const setFreqDiv = (val: number) => freqDiv = val;
export const setSpectrumAutoset = (val: boolean) => autoset = val;
export const setSpectrumSaveFlag = (val: boolean) => saveFlag = val;
export const setWindowType = (val: WindowFunction) => windowType = val;
export const setCenter = (val: number) => center = val;
export const setFFTSize = (val: number) => fftSize = val;
export const setChannel1Enabled = (val: boolean) => channel1.setEnabled(val);
export const setChannel2Enabled = (val: boolean) => channel2.setEnabled(val);

interface Callbacks {
  changeCenter: (center: number) => void,
  finishAutoset: () => void,
  finishSave: () => void,
}

export const drawSpectrumWave = (callbacks: Callbacks) => {

  clearInterval(fillDataArrayInterval);
  setupWaveDataPopulation(channel1, channel2, fillDataArrayInterval);


  // Creating new Paper objects will error if done globally
  // That is why thse lines are here instead of outside the function
  let waveLayer = new Paper.Layer();
  channel1.createPath();
  channel2.createPath();
  channel1.init();
  channel2.init();

  Paper.view.on('frame', function () {
    waveLayer.activate();
    handleAutoset(callbacks);
    handleSave(callbacks);
    channel1.draw(center, decibelsDiv, freqDiv, fftSize, windowType);
    channel2.draw(center, decibelsDiv, freqDiv, fftSize, windowType);
  });
  

  Paper.view.on('resize', function (event: any) {
    waveLayer = new Paper.Layer();
    waveLayer.activate();
    channel1.init();
    channel2.init();
  });
}


function handleAutoset(callbacks: Callbacks) {
  if (!autoset) return;
  const channel1PeakFrequency = channel1.getPeakFrequency();
  const channel2PeakFrequency = channel2.getPeakFrequency();
  const middleFrequency = (channel1PeakFrequency + channel2PeakFrequency) / 2;
  const bothChannelsEnabled = channel1._enabled && channel2._enabled;

  if (bothChannelsEnabled)
    callbacks.changeCenter(middleFrequency);
  else if (channel1._enabled)
    callbacks.changeCenter(channel1PeakFrequency);
  else if (channel2._enabled)
    callbacks.changeCenter(channel2PeakFrequency);

  autoset = false;
  callbacks.finishAutoset();
}


function handleSave(callbacks: Callbacks) {
  if (!saveFlag) return;
  channel1.save();
  channel2.save();
  saveFlag = false;
  callbacks.finishSave();
}
