import React, { useState, useContext, useEffect, useCallback } from 'react';
import {IonContent, IonPage, IonButton, IonRange} from '@ionic/react';
import {
    AppContext, setCarrierFrequencyAction, setMessageFrequencyAction, setAmplitudeAction,
    setCurrChannelAction, setChannelOutputtingAction,
    getCarrierFrequency, getMessageFrequency, getAmplitude, getActiveChannel,
    getTargetChannel, getOutputting, setModulationModeAction, getModulation,
} from '../State';

import type { WAVETYPE } from '../State';

import { FunctionGeneratorAudio } from '../components/FunctionGeneratorAudio';

import './Pages.css';
import PageHeader from '../components/PageHeader';
import KeyboardInputPopover from '../components/KeyboardInputPopover';
import { clamp } from '../utils/MathUtils';

const AMFM: React.FC = () => {

    // Context
    const minCarrierFrequency = 550;
    const maxCarrierFrequency = 20000;
    const minMessageFrequency = 1;
    const minAmplitudePercentage = 0;
    const maxAmplitudePercentage = 100;
    const { state, dispatch } = useContext(AppContext);

    // Effect for disabling channels outputting when leaving page
    useEffect(() => {

        // Cleanup
        return () => {
            dispatch(setChannelOutputtingAction(0, false));
            dispatch(setChannelOutputtingAction(1, false));
        }
    }, [dispatch]);

    const name = "Amplitude Modulation/Frequency Modulation";

    // Selected channel obj
    const activeChannel = getActiveChannel(state);

    // Left-right channels
    const chOne = getTargetChannel(state, 0);
    const chTwo = getTargetChannel(state, 1);

    // Get and set frequency
    const carrierFrequency = getCarrierFrequency(activeChannel);
    const setCarrierFrequency = useCallback((freq: number) => {
        dispatch(setCarrierFrequencyAction(freq));
    }, [dispatch]);

    // Get both channel frequencies
    const chOneFrequency = getCarrierFrequency(chOne);
    const chTwoFrequency = getCarrierFrequency(chTwo);

    // Get and set frequency
    const messageFrequency = getMessageFrequency(activeChannel);
    const setMessageFrequency = useCallback((msgFreq: number) => {
        dispatch(setMessageFrequencyAction(msgFreq));
    }, [dispatch]);

    // Get both channel frequencies
    const chOneMessageFrequency = getMessageFrequency(chOne);
    const chTwoMessageFrequency = getMessageFrequency(chTwo);

    // Get and set amplitude
    const amplitude = getAmplitude(activeChannel);
    const setAmplitude = useCallback((amp: number) => {
        dispatch(setAmplitudeAction(Math.max(0, amp)));
    }, [dispatch]);

    // Get both channel amplitude
    const chOneAmplitude = getAmplitude(chOne);
    const chTwoAmplitude = getAmplitude(chTwo);

    // Get and set current channel
    const currChannel = state.currChannel;
    const setCurrChannel = useCallback((channel: 0 | 1) => {
        dispatch(setCurrChannelAction(channel));
    }, [dispatch]);

    // Get and set channels outputting
    const chOneOutputting = getOutputting(chOne);
    const chTwoOutputting = getOutputting(chTwo);

    const toggleChOneOutputting = useCallback(() => {
        dispatch(setChannelOutputtingAction(0, !chOneOutputting));
    }, [chOneOutputting, dispatch]);

    const toggleChTwoOutputting = useCallback(() => {
        dispatch(setChannelOutputtingAction(1, !chTwoOutputting));
    }, [chTwoOutputting, dispatch]);

    const chOneModulation = getModulation(chOne);
    const chTwoModulation = getModulation(chTwo);

    const amChOneModulation = useCallback(() => {
        dispatch(setModulationModeAction(true))
    }, [dispatch]);

    const fmChOneModulation = useCallback(() => {
        dispatch(setModulationModeAction(false))
    }, [dispatch]);

    const amChTwoModulation = useCallback(() => {
        dispatch(setModulationModeAction(true))
    }, [dispatch]);

    const fmChTwoModulation = useCallback(() => {
        dispatch(setModulationModeAction(false))
    }, [dispatch]);

    // For showing and hiding popovers
    const [frequencyPopoverHidden, setFrequencyPopoverHidden] = useState(true);
    const [amplitudePopoverHidden, setAmpltitudePopoverHidden] = useState(true);
    const [messageFrequencyPopoverHidden, setMessageFrequencyPopoverHidden] = useState(true);

    /**
     * Set the Frequency from the popover
     * @return {[type]} [description]
     */
    function popoverFrequencySet(value: number | undefined) {
        setFrequencyPopoverHidden(true);
        if(value === undefined) return;
        setCarrierFrequency(clamp(value, minCarrierFrequency, maxCarrierFrequency));
    }

    /**
     * Set the Message Frequency from the popover
     * @return {[type]} [description]
     */
    function popoverMessageFrequencySet(value: number | undefined) {
        setMessageFrequencyPopoverHidden(true);
        if(value === undefined) return;
        setMessageFrequency(clamp(value, minMessageFrequency, Math.round(carrierFrequency / 10)));
    }

    /**
     * Set the Amplitude from the popover
     * @return {[type]} [description]
     */
    function popoverAmplitudeSet(value: number | undefined) {
        setAmpltitudePopoverHidden(true);
        if(value === undefined) return;
        setAmplitude(clamp(value, minAmplitudePercentage, maxAmplitudePercentage));
    }

    const chOneValues = {
        active: chOneOutputting,
        frequency: chOneFrequency,
        messageFrequency: chOneMessageFrequency,
        amplitude: chOneAmplitude / 100,
        phase: 0, waveform: "custom" as WAVETYPE,
        modulation: chOneModulation
    };
    const chTwoValues = {
        active: chTwoOutputting,
        frequency: chTwoFrequency,
        messageFrequency: chTwoMessageFrequency,
        amplitude: chTwoAmplitude / 100,
        phase: 0,
        waveform: "custom" as WAVETYPE,
        modulation: chTwoModulation
    };

    return (
        <IonPage>
            <PageHeader
                name={name}
                hidden={false}
                isConnectHidden={true}
                tutorialPath={"AMFM"}
            />
            <IonContent fullscreen scrollY={false} color="secondary">
                <FunctionGeneratorAudio chOne={chOneValues} chTwo={chTwoValues} />
                <div className="frequency-waveform-channels-AMFM">

                    {/* Channel 1 Editing Button */}
                    <div className="channel-div-AMFM">
                        <IonButton className="edit-button-L-AMFM" mode="ios" onClick={() => { setCurrChannel(0) }} color={currChannel === 0 ? "primary" : "light"} data-testid="left-edit">
                            <div className="edit-button-contents-AMFM">
                                CH1 <br />
                                C-FQ: {Math.round(chOneFrequency)} Hz <br />
                                M-FQ: {Math.round(chOneMessageFrequency)} Hz<br/>
                                AMP: {chOneAmplitude}% <br />
                                MODE: {chOneModulation ? "AM" : "FM"} <br />
                            </div>
                        </IonButton>
                    </div>

                    <div className="frequency-and-waveform-AMFM">

                        {/* Carrier Frequency Button and Slider */}
                        <div className="frequency-button-div-AMFM">
                            <IonButton className="frequency-button-AMFM" mode="ios" color="light" onClick={() => setFrequencyPopoverHidden(false)} data-testid="frequency-button">
                                Carrier Frequency: {Math.round(carrierFrequency)} Hz
                            </IonButton>
                        </div>

                        <div>
                            <IonRange class="range-frequency-AMFM" mode="ios" value={Math.log(carrierFrequency - minCarrierFrequency)} min={-1} max={Math.log(20000 - minCarrierFrequency)} step={.0000000001}
                                onIonChange={e => setCarrierFrequency(Math.exp(e.detail.value as any) + minCarrierFrequency)} data-testid="frequency-range" />
                        </div>

                        {/* Message Frequency Button and Slider */}
                        <div className="message-frequency-button-div-AMFM">
                            <IonButton className="message-frequency-button-AMFM" mode="ios" color="light" onClick={() => setMessageFrequencyPopoverHidden(false)}
                                data-testid="message-frequency-button">
                                Message Frequency: {Math.round(messageFrequency)} Hz
                            </IonButton>
                        </div>

                        <div>
                            <IonRange class="range-message-frequency-AMFM" mode="ios" value={messageFrequency} min={1} max={carrierFrequency / 10} step={.0000000001}
                                onIonChange={e => setMessageFrequency(e.detail.value as any)} data-testid="message-frequency-range" />
                        </div>
                    </div>

                    {/* Channel 2 Editing Button */}
                    <div className="channel-div-AMFM">
                        <IonButton className="edit-button-R-AMFM" mode="ios" onClick={() => { setCurrChannel(1) }} color={currChannel === 1 ? "primary" : "light"} data-testid="right-edit">
                            <div className="edit-button-contents-AMFM">
                                CH2 <br />
                                C-FQ: {Math.round(chTwoFrequency)} Hz <br />
                                M-FQ: {Math.round(chTwoMessageFrequency)} Hz<br/>
                                AMP: {chTwoAmplitude}% <br />
                                MODE: {chTwoModulation ? "AM" : "FM"} <br />
                            </div>
                        </IonButton>
                    </div>

                </div>

                {/* Amplitude, Start/Stop Buttons, Phase */}
                <div className="amplitude-start-phase-AMFM">

                    {/* Amplitude Button and Slider */}
                    <div className="amplitude-components2-AMFM">
                        <IonButton className="amplitude-button-AMFM" mode="ios" color="light" onClick={() => setAmpltitudePopoverHidden(false)} data-testid="amplitude-button">
                            Amplitude: {amplitude}%
                        </IonButton>
                        <IonRange class="range-amplitude-AMFM" mode="ios" value={amplitude} min={0} max={100} step={1} onIonChange={e => setAmplitude(e.detail.value as any)} data-testid="amplitude-range" />
                    </div>

                    {/* Play/Pause Buttons */}
                    <div className="start-buttons-AMFM">
                        {/* CH1 Play/Pause Button */}
                        <IonButton className="hold-button-AMFM" mode="ios" onClick={() => { toggleChOneOutputting() }} color={chOneOutputting ? "primary" : "light"} data-testid="left-play">
                            <div className="edit-button-contents-AMFM">
                                CH1
                                <img className="play-pause-img-AMFM" src={process.env.PUBLIC_URL + (chOneOutputting ? "/assets/pause.png" : "/assets/play.png")} alt="" ></img>
                            </div>
                        </IonButton>

                        {/* CH2 Play/Pause Button */}
                        <IonButton className="hold-button-AMFM" mode="ios" onClick={() => { toggleChTwoOutputting() }} color={chTwoOutputting ? "primary" : "light"} data-testid="right-play">
                            <div className="edit-button-contents-AMFM">
                                CH2
                                <img className="play-pause-img-AMFM" src={process.env.PUBLIC_URL + (chTwoOutputting ? "/assets/pause.png" : "/assets/play.png")} alt="" ></img>
                            </div>
                        </IonButton>
                    </div>

                    <div className="AMFM-toggle-div">
                        <IonButton className="modulation-button-AMFM" mode="ios" onClick={() => { currChannel ? amChTwoModulation() : amChOneModulation() }} color={currChannel ? (chTwoModulation ? "primary" : "light") : (chOneModulation ? "primary" : "light")} data-testid="modulation-button">
                            <div className="edit-button-contents-AMFM">
                                AM
                            </div>
                        </IonButton>
                        <IonButton className="modulation-button-AMFM" mode="ios" onClick={() => { currChannel ? fmChTwoModulation() : fmChOneModulation() }} color={currChannel ? (chTwoModulation ? "light" : "primary") : (chOneModulation ? "light" : "primary")} data-testid="modulation-button2">
                            <div className="edit-button-contents-AMFM">
                                FM
                            </div>
                        </IonButton>
                    </div>
                </div>

                {/* Carrier Frequency Popover */}
                <KeyboardInputPopover hidden={frequencyPopoverHidden} minInput={minCarrierFrequency} maxInput={maxCarrierFrequency} inputUnits="Hz" onClose={popoverFrequencySet}/>

                {/* Message Frequency Popover */}
                <KeyboardInputPopover hidden={messageFrequencyPopoverHidden} minInput={minMessageFrequency} maxInput={Math.round(carrierFrequency / 10)} inputUnits="Hz" onClose={popoverMessageFrequencySet}/>

                {/* Amplitude Popover */}
                <KeyboardInputPopover hidden={amplitudePopoverHidden} minInput={minAmplitudePercentage} maxInput={maxAmplitudePercentage} inputUnits="%" onClose={popoverAmplitudeSet}/>

            </IonContent>
        </IonPage>
    );
};

export default AMFM;
