/*
  About: This file is used to create the triggers and the channel offsets for the oscilloscope. 
  This is done with the use of PaperJS. The position of trigger and channel offsets are passed to 
  the Oscope Wave with useEffects
*/

import Paper from "paper";
import { Axis } from "../enums/Axis";
import { Draggable } from "./Draggable";

let channel1Enabled = true;
let channel2Enabled = false;
let channelButtonPressed = false;
let channel1 = new Draggable(Axis.eVertical);
let channel2 = new Draggable(Axis.eVertical);
let timeTrigger = new Draggable(Axis.eHorizontal);
let voltTrigger = new Draggable(Axis.eVertical);
export const setChannel1EnabledForDraggables = (val: boolean) => { channel1Enabled = val; channelButtonPressed = true; }
export const setChannel2EnabledForDraggables = (val: boolean) => { channel2Enabled = val; channelButtonPressed = true; }

interface Callbacks {
  changeTriggers: (timeValue: number, voltValue: number) => void,
  changeYOffsets: (channel1Value: number, channel2Value: number) => void
}

const DrawDraggables = (callbacks: Callbacks) => {

  let layer = new Paper.Layer();
  let timePos = .5;
  let voltPos = .5;
  let timeDiff = 0.5;
  let voltDiff = 0;
  channel1.setPath("#D00000", .75);
  channel2.setPath("#4169E1", .25);
  timeTrigger.setPath();
  voltTrigger.setPath();

  Paper.view.onFrame = function () {
    if (!channelButtonPressed) return;
    // If a channel button has been pressed we want to change the y offsets of the waves and change their visibility
    if (channel1Enabled && channel2Enabled) {
      channel1.setVisibility(true);
      channel2.setVisibility(true);
      channel1.setPosition(.75);
      channel2.setPosition(.25);
    } else {
      channel1.setVisibility(false);
      channel2.setVisibility(false);
      channel1.setPosition(.5);
      channel2.setPosition(.5);
    }
    callbacks.changeYOffsets(channel1.getY(), channel2.getY());
    channelButtonPressed = false;
  }

  Paper.view.onMouseDown = function (event: any) {
    timeTrigger.mousedown(event);
    voltTrigger.mousedown(event);
    channel1.mousedown(event);
    channel2.mousedown(event);
  }

  Paper.view.onMouseDrag = function (event: any) {
    if (timeTrigger.getSelected()) {
      timePos = timeTrigger.mousedrag(event) ?? timePos;
    } else if (voltTrigger.getSelected()) {
      voltPos = voltTrigger.mousedrag(event) ?? voltPos;
    } else if (channel1.getSelected()) {
      channel1.mousedrag(event);
    } else if (channel2.getSelected()) {
      channel2.mousedrag(event);
    }

    timeDiff = timePos;
    voltDiff = 2*voltPos - 1;

    // When draggables are dragged they will update the oscope wave
    callbacks.changeTriggers(timeDiff, voltDiff);
    callbacks.changeYOffsets(channel1.getY(), channel2.getY());
  }

  Paper.view.onMouseUp = function (event: any) {
    timeTrigger.mouseup(event);
    voltTrigger.mouseup(event);
    channel1.mouseup(event);
    channel2.mouseup(event);
  };

  Paper.view.on('resize', function (event: any) {
    layer.activate();
    timeTrigger.resize(event);
    voltTrigger.resize(event);
    channel1.resize(event);
    channel2.resize(event);
  });
}


export default DrawDraggables;

