import Paper from "paper";
import exportCSV from "./exportCSV";
import { TriggerState } from "../enums/TriggerState";
import { serialConnection } from "./Serial";
import { time } from "console";

//.707 VRMS = -1 to 1 V AC
//No resistance (no adapter): 149 Hz
//With resistance (adapter): 91 Hz
const voltageMultiplierConstant = .5 * .9;

export class OscopeChannelWave {
    _enabled: boolean;
    _voltDiv: number = .5;
    _yOffset: number = 0;
    _bufferSize: number = 8192;
    _data: Float32Array = new Float32Array(this._bufferSize);
    _path: paper.Path | undefined;
    _triggerEnabled: boolean = true;
    _drawing: boolean = true;
    _color: string;
    _maxPoints: number = 200; // maximum points plotted for a line
    lastNumPoints: number = -1;
    
    constructor (enabled: boolean, color: string) {
        this._enabled = enabled;
        this._color = color;
    }

    setEnabled (enabled: boolean) {
        this._enabled = enabled;
        if (!this._path) return;
        this._path.visible = enabled;
    }

    setData (data: Float32Array) {
        if (!this._drawing) return;
        this._data = data;
    }

    setVoltDiv (voltDiv: number) {
        this._voltDiv = voltDiv;
    }

    setYOffset (yOffset: number) {
        this._yOffset = yOffset;
    }

    setTriggerEnabled (triggerEnabled: boolean) {
        this._triggerEnabled = triggerEnabled;
    }

    setDrawing (drawing: boolean) {
      this._drawing = drawing;
    }

    createPath () {
        this._path = new Paper.Path(
          {strokeColor: this._color, visible: this._enabled}
        );
    }

    getXDiv () {
      let xDiv = 10000.0 / this.getFrequency();
      if (xDiv > 0.75) { // if above 0.75 threshold, round to nearest integer
          return Math.round(xDiv);
      } else { // if below 0.75, round to nearest power of 2 (0.5, 0.25, 0.125, etc)
        let power = 1;
        while (power > xDiv) {
            power /= 2;
        }
        let nextPower = power / 2;
        
        return (xDiv - nextPower < power - xDiv) ? nextPower : power;
      } 
    }

    /**
     * Resets the points to the x axis
     * @returns
     */
    init (numPoints: number) {
        if (!this._path) return;
        this._path.removeSegments();
        // Place points on the x axis so then we only modify the y coordinate when we draw
        for (let i = 0; i <= numPoints; i++) {
          const xScreen = (i / numPoints) * Paper.view.size.width;
          const yScreen = (1 / 2) * Paper.view.size.height;
          const point = new Paper.Point(xScreen, yScreen);
          this._path.add(point);
        }
    }

    /**
     * Determines the frequency of the wave based on how many times it crosses the x axis
     * @returns frequency of the wave
     */
    getFrequency() {
        const [minVoltage, maxVoltage] = this.getMaxVoltage();
        const midPoint = (maxVoltage - minVoltage) * 0.5 + minVoltage;
        let crossCount = 0;
        let firstIndex = -1;
        for(let i = 0; i < this._data.length - 1; i++){
          let point1 = this._data[i];
          let point2 = this._data[i+1];
          if (point1 === midPoint || (point1 < midPoint && point2 > midPoint) || (point1 > midPoint && point2 < midPoint)) {
            firstIndex = (!crossCount) ? i : firstIndex
            crossCount++;
          }
        }
        if (firstIndex === -1) return 0;
        let frequency = ( serialConnection.getSampleRate() * 0.5 * (crossCount - 1.0) / this._data.length ); // -1 to get rid of last cross, *0.5 for a full cycle
        return frequency;
    }

    /**
     * Finds a point in the middle of the wave to trigger on (if there is one)
     * @param triggerState Rising, Falling, or Single Trigger
     * @param voltDiff location of the volt trigger on the left side of the graph
     * @returns index of the trigger point (zero if there is no trigger point)
     */
    getTrigger(triggerState: TriggerState, voltDiff: number) {
        let triggerPoint = 0;
        let triggerVoltage = (voltDiff*this._voltDiv)/voltageMultiplierConstant;
        // We start at the half way point so the wave is centered on the graph
        for(let i = Math.floor(this._data.length/2); i < this._data.length-1; i++){
          let point1 = this._data[i];
          let point2 = this._data[i+1];
          if(triggerState === TriggerState.eRising){
            if(point1 <= triggerVoltage && point2 > triggerVoltage){
              triggerPoint = i;
              break;
            }
          } else if (triggerState === TriggerState.eFalling) {
            if(point1 >= triggerVoltage && point2 < triggerVoltage){
              triggerPoint = i;
              break;
            }
          }
        }
        return triggerPoint;
    }

    getMaxVoltage() {
        let maxVoltage = this._data[0];
        let minVoltage = maxVoltage;
        for(let i = 0; i < this._data.length; i++){
          const voltage = this._data[i] * 2;
          if (voltage > maxVoltage) {
            maxVoltage = voltage;
          }
          if (voltage < minVoltage) {
            minVoltage = voltage;
          }
        }
        return [minVoltage, maxVoltage];
    }

    save () {
      if (!this._enabled) return;
      exportCSV(this._data);
    }

    /**
     * Called when autoset button is pressed
     * @param bothChannelsEnabled whether or not both channels are enabled
     * @returns The timeDiv and voltDiv that will set if only this channel is enabled
     */
    autoset (bothChannelsEnabled: boolean) {
      const [minVoltage, maxVoltage] = this.getMaxVoltage();
      const magnitude = (maxVoltage - minVoltage) / 2;
      
      const tempVoltDiv = Math.min(Math.max(Math.round(.5 * 10 * magnitude) / 10, .1), 4.9);
      this._voltDiv = bothChannelsEnabled ? (tempVoltDiv * 2) : tempVoltDiv;
      
      return { xDiv: this.getXDiv(), yDiv: this._voltDiv };
    }

    /**
     * Sets the y coordinate of points on the graph
     * @param triggerState Rising, Falling, or Single Trigger
     * @param timeDiv The amount of time a block of the graph represents (1-20)
     * @param voltDiff Location of the volt trigger on the left of the graph
     * @param timeDiff Location of the time trigger on the top of the graph
     * @returns
     */
    draw (triggerState: TriggerState, timeDiv: number, voltDiff: number, timeDiff: number, bothChannelsEnabled: boolean) {

       if (this._path === undefined) return;
        const height = Paper.view.size.height;
        const yOffsetFromOrigin = this._yOffset - (height / 2);
        const triggerIndex = this.getTrigger(triggerState, voltDiff);
        let numPoints = 0;
        
        if (bothChannelsEnabled) {
          timeDiv *= 0.5; 
        }
        if (timeDiv > 1) {
          timeDiv = Math.floor(timeDiv);
        }

        if (timeDiv < 1) {
          numPoints = Math.floor(this._maxPoints * timeDiv); 
        } else {
          numPoints = this._maxPoints;
        }

        if (numPoints != this.lastNumPoints) {
          this.init(numPoints)
          this.lastNumPoints = numPoints;
        }

        let dataIndexOfTheLeftmostPointOnTheGraph = 0;
        // Finds the first data point to be graphed based on the location of the Time Trigger and the current Time Div
        if(triggerIndex !== 0 && this._triggerEnabled){
          let numberOfDataPointsLeftOfTheTimeTrigger = ((timeDiff * this._maxPoints * timeDiv) | 0); // ensures it is an integer
          dataIndexOfTheLeftmostPointOnTheGraph = triggerIndex - numberOfDataPointsLeftOfTheTimeTrigger;
        }

        let segment_index = 0;
        for (let i = 0; i <= this._maxPoints; i++) {

          let multiplier = i * timeDiv;
          if (!Number.isInteger(multiplier)) {
            continue
          }

          let dataIndex = dataIndexOfTheLeftmostPointOnTheGraph + multiplier;
          let dataPoint = this._data[dataIndex];

          // Flip vertically for rendering
          dataPoint = -dataPoint;

          // Scale voltage
          dataPoint = (dataPoint / this._voltDiv) * voltageMultiplierConstant;

          // Set the y coordinate of the ith segment point
          let segment = this._path.segments[segment_index];
          segment.point.y = ((dataPoint + 1) * (height / 2)) + yOffsetFromOrigin;
          segment_index++;
        }
    }
}