// Get current channel object
/**
 * getActiveChannel
 * @param  state: AppStateInterface Current App State
 * @return FuncGenChannelInterface  Returns the Current Channel Interface
 */
export const getActiveChannel = (state: AppStateInterface) => 
  (getTargetChannel(state, state.currChannel));

/**
 * getTargetChannel
 * @param  state:  AppStateInterface Current App State
 * @param  number target: 0|1 The Frequency Channel to Target
 * @return FuncGenChannelInterface  The Targetted Frequency Channel from the current state.           
 */
export const getTargetChannel = (state: AppStateInterface, target: 0 | 1) => 
  (target === 0 ? state.channelOne : state.channelTwo);

