import { IonButton } from "@ionic/react";
import './Buttons.css';

type Props = {
  hidden: boolean,
  onClick: () => void
};

/**
 * This button component is to toggle addtional display information when in fullscreen.
 * @param  boolean options.hidden  Should we hide the button
 * @param  function(): void options.onClick runs a function when clicked.
 * @return                  Renderable
 */
const FullscreenDisplayButton: React.FC<Props> = ({ hidden, onClick }) => {

  return (
    <IonButton className="fullscreen-display-button"
               onClick = {() => onClick()} 
               mode="ios" 
               fill="clear"
               hidden={hidden}>
      <img className="display-icon" src={process.env.PUBLIC_URL + "/assets/displayoff.png"} alt=""></img>
    </IonButton>
  );
};

export default FullscreenDisplayButton;
