import React, { useState, useEffect } from 'react';
import './Pages.css';
import LogicAnalyzerScope from '../components/scopes/LogicAnalyzerScope';
import WakeLock from '../components/WakeLock';
import PageHeader from '../components/PageHeader';
import FullscreenDisplayButton from '../buttons/FullscreenDisplayButton';
import FullscreenExitButton from '../buttons/FullscreenExitButton';
import WaveInfoDisplay, { WaveInfoDisplayElement } from '../components/WaveInfoDisplay';
import KeyboardInputPopover from '../components/KeyboardInputPopover';
import TriggerStateLA from '../enums/TriggerStateLA';
import DecodingMode from '../enums/DecodingMode';
import {
    isPlatform,
    IonButton,
    IonContent,
    IonPage,
    IonPopover,
    IonModal,
    IonSelect,
    IonItem,
    IonList,
    IonSelectOption,
    IonAlert,
} from '@ionic/react';
import { serialConnection } from '../components/Serial';

const LogicAnalyzer: React.FC = () => {
    const [channelNames, setChannelNames] = useState([
        "Ch 1",
        "Ch 2",
        "Ch 3",
        "Ch 4",
        "Ch 5",
        "Ch 6",
        "Ch 7",
        "Ch 8",
    ]);

    const [renameIndex, setRenameIndex] = useState(-1);

    const [sampleCount, setSampleCount] = useState(5000);
    const [sampleRate, setSampleRate] = useState(10000);
    const [zoomLevel, setZoomLevel] = useState(1);
    const [sampleLeft, setSampleLeft] = useState(0);
    const [sampleRight, setSampleRight] = useState(5000);
    const [showModal, setShowModal] = useState(false);

    const name = "Logic Analyzer";
    const triggerOptions = [TriggerStateLA.eDisabled, TriggerStateLA.eRising, TriggerStateLA.eFalling,];
    const decodingModes = [DecodingMode.eDisabled, DecodingMode.eTiming, DecodingMode.ePWM];

    const [triggerState, setTriggerState] = useState(TriggerStateLA.eDisabled);
    const [triggerChannel, setTriggerChannel] = useState(0);
    const [decodingMode, setDecodingMode] = useState(DecodingMode.eDisabled);
    const [decodingChannel, setDecodingChannel] = useState(0);
    const [decodingPopoverHidden, setDecodingPopoverHidden] = useState(true);
    const [fullscreenFlag, setFullscreenFlag] = useState(true);
    const [displayFlag, setDisplayFlag] = useState(true);
    const [cursorFlag, setCursorFlag] = useState(false);
    const [threshold, setThreshold] = useState(0.2);
    const [timeDiff, setTimeDiff] = useState(0);
    const [triggerPopoverHidden, setTriggerPopoverHidden] = useState(true);
    const [thresholdPopoverHidden, setThresholdPopoverHidden] = useState(true);
    const [playingFlag, setPlaying] = useState(true);

    useEffect(() => {
        sessionStorage.setItem("Samples", JSON.stringify(sampleCount));
        sessionStorage.setItem("Threshold", JSON.stringify(threshold));
        sessionStorage.setItem("TimeDiff", JSON.stringify(timeDiff));
        // let storedValue = sessionStorage.getItem("Samples");
        // let value = storedValue !== null ? parseInt(storedValue, 10) : 5000;
        // setSampleCount(value);
    }, [sampleCount, threshold, timeDiff]);

    const togglePlayPause = () => {
        setPlaying(!playingFlag);
    };

    function changeZoom(direction: number) {
        setZoomLevel((prevZoom) => {
            return Math.min(Math.max(prevZoom + direction, 1), 10);
        });
    }

    useEffect(() => {
        if (zoomLevel === 1) {
            setSampleLeft(0);
            setSampleRight(sampleCount);
        } else {
            const power = Math.pow(2, zoomLevel - 1);
            const sampleWidth = Math.floor(sampleCount / power);
            const currLeft = Math.min(Math.max(sampleLeft, 0), sampleCount);
            const newRight = Math.min(currLeft + sampleWidth, sampleCount);
            const newLeft = newRight - sampleWidth;
            setSampleLeft(newLeft);
            setSampleRight(newRight);
        }
    }, [zoomLevel, sampleCount, sampleLeft])

    useEffect(() => {
        setPlaying(false);
        setZoomLevel(1);
    }, [sampleCount, sampleRate, triggerChannel, triggerState])

    useEffect(() => {
        serialConnection.setLATrigger(triggerState, triggerChannel);
    }, [triggerChannel, triggerState])

    function changeScroll(direction: number) {
        if (direction !== -1 && direction !== 1) return;
        const power = Math.pow(2, zoomLevel - 1);
        const sampleWidth = Math.floor(sampleCount / power);
        const diffSamples = Math.round(sampleWidth / 5) * direction;
        const currLeft = Math.min(Math.max(sampleLeft + diffSamples, 0), sampleCount);
        const newRight = Math.min(currLeft + sampleWidth, sampleCount);
        const newLeft = newRight - sampleWidth;
        setSampleLeft(newLeft);
        setSampleRight(newRight);
    }

    function changeCursorDiff(timeDiff: number, voltDiff: number) {
        setTimeDiff(timeDiff);
    }

    function changeDisplayFlag() {
        setDisplayFlag(!displayFlag);
    }

    function changeFullscreenFlag() {
        setFullscreenFlag(!fullscreenFlag);
    }

    function changeCursorFlag() {
        setCursorFlag(!cursorFlag)
    }

    function popoverThresholdMenuSet(value: number | undefined) {
        setThresholdPopoverHidden(true);
        if (value === undefined) return;
        setThreshold(value);
    }

    function calculateTime() {
        const numSamples = sampleRight - sampleLeft;
        const timePerSample = 1 / sampleRate * 1000;
        return (numSamples * timePerSample * timeDiff).toFixed(4)
    }

    function getTriggerDescription() {
        if (triggerState === TriggerStateLA.eDisabled) {
            return 'Disabled'
        }

        return `${channelNames[triggerChannel]} ${triggerState}`
    }

    function getDecodingDescription() {
        if (decodingMode === DecodingMode.eDisabled) {
            return 'Disabled'
        }

        return `${channelNames[decodingChannel]} ${decodingMode}`
    }

    function LAInfo() {
        const elements: WaveInfoDisplayElement[] = [
            { label: 'Samples', value: sampleCount.toString(), unit: '', isCursor: false },
            { label: 'Frequency', value: sampleRate.toString(), unit: 'Hz', isCursor: false },
            { label: 'Time', value: calculateTime(), unit: 'ms', isCursor: true },
            { label: 'Trigger', value: getTriggerDescription(), unit: '', isCursor: false },
            { label: 'Decoding', value: getDecodingDescription(), unit: '', isCursor: false}
        ];

        return elements;
    }

    return (
        <IonPage>
            <PageHeader
                name={name}
                hidden={!fullscreenFlag}
                isConnectHidden={false}
                onFullscreenClick={changeFullscreenFlag}
                tutorialPath={"LogicAnalyzer"}
                isSettingHidden={true}
            />

            <IonContent fullscreen scrollY={false} color="secondary">
                <div className={`LA-full-screen`}>

                    <FullscreenExitButton hidden={fullscreenFlag} onClick={changeFullscreenFlag} />
                    <FullscreenDisplayButton hidden={fullscreenFlag} onClick={changeDisplayFlag} />
                    <WaveInfoDisplay
                        hidden={displayFlag || fullscreenFlag}
                        isFullscreen={true}
                        cursorFlag={cursorFlag}
                        elements={LAInfo()}
                        color={"#D00100"}
                    />
                    <WakeLock enabled={true} />
                    <div className={fullscreenFlag ? "LA-div" : "LA-div-full"}>
                        <div className={fullscreenFlag ? "logic-container" : "logic-container-full"}>
                            {/* Spacer */}
                            <div/>
                            {/* LA Time range and scroll bar */}
                            <div>
                                <div style={{ display: 'flex', justifyContent: 'center' }}>
                                    <label style={{ color: 'black' }}>
                                        {(sampleLeft * 1 / sampleRate * 1000).toFixed(2)}ms to {(sampleRight * 1 / sampleRate * 1000).toFixed(2)}ms
                                    </label>
                                </div>
                                <div
                                    style={{
                                        border: '1px solid black',
                                        borderRadius: '4px',
                                        width: '100%',
                                        height: '20px',
                                        position: 'relative',
                                    }}
                                >
                                    <div style={{
                                        position: 'absolute',
                                        borderRadius: '4px',
                                        left: `${(sampleLeft / sampleCount) * 100}%`,
                                        width: `${((sampleRight - sampleLeft) / sampleCount) * 100}%`,
                                        height: '100%',
                                        backgroundColor: 'black',
                                    }} />
                                </div>
                            </div>
                            {/* LA Buttons */}
                            <div className={(!fullscreenFlag) ? "logic-button-hidden" : `logic-button`}>
                                {
                                    channelNames.map((name, index) => (
                                        <IonButton
                                            key={index}
                                            onClick={() => setRenameIndex(index)}
                                        >
                                            {name}
                                        </IonButton>
                                    ))
                                }
                                <IonButton
                                    hidden={decodingMode === DecodingMode.eDisabled}
                                >
                                    {decodingMode}
                                </IonButton>
                            </div>
                            <LogicAnalyzerScope
                                className="logicgraph"
                                sampleCount={sampleCount}
                                sampleRate={sampleRate}
                                isFullscreen={fullscreenFlag}
                                playingFlag={playingFlag}
                                setPlaying={setPlaying}
                                cursorChangeCallback={changeCursorDiff}
                                cursorFlag={cursorFlag}
                                zoomLevel={zoomLevel}
                                changeZoom={changeZoom}
                                sampleLeft={sampleLeft}
                                sampleRight={sampleRight}
                                changeScroll={changeScroll}
                                decodingMode={decodingMode}
                                decodingChannel={decodingChannel}
                            />
                        </div>
                    </div>

                    {/* The buttons on the right hand side of the graph */}
                    <div className={fullscreenFlag ? "LA-side-data" : "LA-side-data-hidden"}>
                        <div className="LA-first-row-div"> {/* First row of UI buttons - Time Div */}
                            <IonButton className="LA-button-side" mode="ios" onClick={() => changeZoom(-1)} color="tertiary" data-testid="time-div-neg-button">
                                <div>
                                    <div>
                                        -
                                    </div>
                                </div>
                            </IonButton>
                            <IonButton className="LA-button-center" mode="ios" color="primary">
                                <div>
                                    <div>
                                        Zoom
                                    </div>
                                </div>
                            </IonButton>
                            <IonButton className="LA-button-side" mode="ios" onClick={() => changeZoom(1)} color="tertiary" data-testid="time-div-pos-button">
                                <div>
                                    <div>
                                        +
                                    </div>
                                </div>
                            </IonButton>
                        </div>

                        <div className="LA-second-row-div"> {/* Second row of UI buttons - Position*/}
                            <IonButton className="LA-button-side" mode="ios" onClick={() => changeScroll(-1)} color="tertiary">
                                <div>
                                    <div>
                                        -
                                    </div>
                                </div>
                            </IonButton>
                            <IonButton className="LA-button-center" mode="ios" color="primary">
                                <div>
                                    Position
                                </div>
                            </IonButton>
                            <IonButton className="LA-button-side" mode="ios" onClick={() => changeScroll(1)} color="tertiary">
                                <div>
                                    <div>
                                        +
                                    </div>
                                </div>
                            </IonButton>
                        </div>

                        <div className="LA-third-row-div"> {/* Third row of UI buttons */}
                            <IonButton id="LA-pause-play-button" className="LA-utility-buttons" mode="ios" onClick={() => togglePlayPause()} color={playingFlag ? "primary" : "tertiary"} data-testid="pause-play-button-os">
                                <div>
                                    <img className="pause-play-img" src={process.env.PUBLIC_URL + (playingFlag ? "/assets/record.png" : "/assets/record-stop.png")} alt="" ></img>
                                    <div>Record</div>
                                </div>
                            </IonButton>
                            <IonButton className="LA-utility-buttons" mode="ios" onClick={() => changeCursorFlag()} color={cursorFlag ? "primary" : "light"} data-testid="cursor-button">
                                <div>
                                    Cursors
                                </div>
                            </IonButton>
                            <IonButton className="LA-utility-buttons" mode="ios" color="light" onClick={() => setTriggerPopoverHidden(false)} data-testid="trigger-button">
                                <div>
                                    Trigger<br />Menu
                                </div>
                            </IonButton>
                            <IonButton className="LA-utility-buttons" mode="ios" color="light" onClick={() => setDecodingPopoverHidden(false)} data-testid="decoding-button">
                                <div>
                                    Decoding<br />Menu
                                </div>
                            </IonButton>
                        </div>
                        <div className="LA-display-div">
                            <span className="helper" />
                            {/* LA Info */}
                            <WaveInfoDisplay
                                hidden={!fullscreenFlag}
                                isFullscreen={false}
                                cursorFlag={cursorFlag}
                                elements={LAInfo()}
                                color={"#D00100"}
                                onClick={() => setShowModal(true)}
                            />
                            <IonModal className="user-modal" isOpen={showModal} onDidDismiss={() => setShowModal(false)}>
                                <IonContent style={{ height: '500px', width: '500px' }}>
                                    <IonList style={{ height: '50%', width: '50%' }}>
                                        <IonItem>
                                            <IonSelect placeholder="Sample Size" value={sampleCount.toString()}
                                                onIonChange={e => setSampleCount(parseInt(e.detail.value, 10))}>
                                                <IonSelectOption value="10000">10 K</IonSelectOption>
                                                <IonSelectOption value="5000">5 K</IonSelectOption>
                                                <IonSelectOption value="1000">1 k</IonSelectOption>
                                                <IonSelectOption value="500">500</IonSelectOption>
                                            </IonSelect>
                                        </IonItem>

                                        <IonItem>
                                            <IonSelect placeholder="Frequency" value={sampleRate.toString()}
                                            onIonChange={e => setSampleRate(parseInt(e.detail.value, 10))}>
                                                <IonSelectOption value="500000">500 kHz</IonSelectOption>
                                                <IonSelectOption value="100000">100 kHz</IonSelectOption>
                                                <IonSelectOption value="10000">10 kHz</IonSelectOption>
                                                <IonSelectOption value="1000">1 kHz</IonSelectOption>
                                                <IonSelectOption value="500">500 Hz</IonSelectOption>
                                                <IonSelectOption value="100">100 Hz</IonSelectOption>
                                            </IonSelect>
                                        </IonItem>
                                    </IonList>
                                    <IonButton onClick={() => setShowModal(false)}>Close</IonButton>
                                </IonContent>
                            </IonModal>
                        </div>
                    </div>
                </div>

                {/* Trigger Menu Popover */}
                <IonPopover
                    isOpen={!triggerPopoverHidden}
                    className={isPlatform("mobile") ? "input-popover2" : "input-popover2-web"}
                    mode="ios"
                    showBackdrop={true}
                    onDidDismiss={() => setTriggerPopoverHidden(true)}
                    data-testid="LA-trigger-popup"
                >
                    {/* First section: Off, Rising, Falling buttons */}
                    <div className="popover-content2">
                        {triggerOptions.slice(0, 3).map((label) => (
                            <IonButton
                                className="trigger-popup-button"
                                key={label}
                                onClick={() => {
                                    setTriggerPopoverHidden(true);
                                    setTriggerState(label);
                                }}
                            >
                                {label}
                            </IonButton>
                        ))}
                    </div>

                    {/* Second section: Dropdown for channel selection */}
                    <div className="popover-content2">
                        <IonItem>
                            <IonSelect
                                placeholder="Select Channel"
                                value={triggerChannel}
                                onIonChange={(e) => setTriggerChannel(e.detail.value)}
                            >
                                {channelNames.map((channel, index) => (
                                    <IonSelectOption value={index}>
                                        {channel}
                                    </IonSelectOption>
                                ))}
                            </IonSelect>
                        </IonItem>
                    </div>
                </IonPopover>

                {/* Threshold Popover */}
                <KeyboardInputPopover hidden={thresholdPopoverHidden} minInput={0.1} maxInput={2} inputUnits="V" onClose={popoverThresholdMenuSet} />

                {/* Decoding Menu Popover */}
                <IonPopover
                    isOpen={!decodingPopoverHidden}
                    className={isPlatform("mobile") ? "input-popover2" : "input-popover2-web"}
                    mode="ios"
                    showBackdrop={true}
                    onDidDismiss={() => setDecodingPopoverHidden(true)}
                    data-testid="LA-decoding-popup"
                >
                    {/* First section: Decoding Mode dropdown */}
                    <div style={{
                        display: 'flex',
                        justifyContent: 'center',
                        alignItems: 'center',
                        padding: '20px',
                        gap: '20px'
                    }}>
                        <div style={{
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            width: '50%'
                        }}>
                            <div style={{
                                marginBottom: '10px',
                                fontWeight: 'bold',
                                color: 'black'
                            }}>
                                Mode
                            </div>
                            <IonSelect
                                placeholder="Select Mode"
                                value={decodingMode}
                                onIonChange={(e) => setDecodingMode(e.detail.value)}
                                style={{ width: '100%', color: 'black' }}
                            >
                                {decodingModes.map((mode) => (
                                    <IonSelectOption value={mode}>
                                        {mode}
                                    </IonSelectOption>
                                ))}
                            </IonSelect>
                        </div>

                    {/* Second section: Channel selection dropdown */}
                        <div style={{
                            display: 'flex',
                            flexDirection: 'column',
                            alignItems: 'center',
                            width: '50%'
                        }}>
                            <div style={{
                                marginBottom: '10px',
                                fontWeight: 'bold',
                                color: 'black'
                            }}>
                                Channel
                            </div>
                            <IonSelect
                                placeholder="Select Channel"
                                value={decodingChannel}
                                onIonChange={(e) => setDecodingChannel(e.detail.value)}
                                style={{ width: '100%', color: 'black' }}
                            >
                                {channelNames.map((channel, index) => (
                                    <IonSelectOption value={index}>
                                        {channel}
                                    </IonSelectOption>
                                ))}
                            </IonSelect>
                        </div>
                    </div>
                </IonPopover>

                {/* IonAlert for renaming channels */}
                <KeyboardInputPopover
                    hidden={thresholdPopoverHidden}
                    minInput={0.1}
                    maxInput={2}
                    inputUnits="V"
                    onClose={popoverThresholdMenuSet}
                />

                {/* IonAlert for renaming channels */}
                <IonAlert
                    isOpen={renameIndex >= 0}
                    onDidDismiss={() => setRenameIndex(-1)}
                    header="Rename Channel"
                    message="Please enter a new name"
                    inputs={[
                        {
                            name: 'newName',
                            type: 'text',
                            // Show current name as placeholder
                            placeholder: renameIndex >= 0 ? channelNames[renameIndex] : ''
                        }
                    ]}
                    buttons={[
                        {
                            text: 'Cancel',
                            role: 'cancel',
                            handler: () => {
                                setRenameIndex(-1);
                            }
                        },
                        {
                            text: 'Ok',
                            handler: (data) => {
                                const newName = data.newName;
                                if (newName && newName.trim() !== "") {
                                    setChannelNames((prevNames) => {
                                        const updated = [...prevNames];
                                        if (renameIndex >= 0) {
                                            updated[renameIndex] = newName;
                                        }
                                        return updated;
                                    });
                                }
                                setRenameIndex(-1);
                            }
                        }
                    ]}
                />
            </IonContent>
        </IonPage>
    );
};

export default LogicAnalyzer;
