
/*
This file is used to display graph on the left side of the screen.
This is done with the use of paperJS.
All that is done is the lines are place on the max and min points of the graph area.
Then a loop is ran to place the intersecting lines of the graph.
*/

import Paper from "paper";
import DecodingMode from "../enums/DecodingMode";

/*
 *
 * This file is used to display graph on the left side of the
 * screen on the oscilloscope page. This is done with the use
 * of paperJS. All that is done is the lines are place on the
 * max and min points of the graph area, then a loop is ran
 * to place the intersecting lines of the graph.
 *

 */

let numOfHBoxes = 8;

export function setNumChannels(channels) {
	numOfHBoxes = channels;
}

const DrawGuideLine = () => {

	// Start a new Layer
	let graphLayer = new Paper.Layer();

	// Function to draw gridlines
	var drawGridLines = function (height, boundingRect) {
		var height_per_rectangle = boundingRect.height / height;
		for (let i = 0; i <= 1; i++) {
			let xPos = boundingRect.left + i * boundingRect.width;
			if (i === 0) xPos += 2;
			if (i === 1) xPos -= 2;
			let topPoint = new Paper.Point(xPos, boundingRect.top);
			let bottomPoint = new Paper.Point(xPos, boundingRect.bottom);
			let aLine = new Paper.Path.Line(topPoint, bottomPoint);
			aLine.strokeColor = "black";
			aLine.strokeWidth = 1;
		}

		//set up horizontal grid lines
		for (let i = 0; i <= height; i++) {
			let yPos = boundingRect.top + i * height_per_rectangle;
			if (i === 0) yPos += 2;
			if (i === height) yPos -= 2;
			let leftPoint = new Paper.Point(boundingRect.left, yPos);
			let rightPoint = new Paper.Point(boundingRect.right, yPos);
			let aLine = new Paper.Path.Line(leftPoint, rightPoint);
			aLine.strokeColor = "black";
			aLine.strokeWidth = 1;
		}
	};

	Paper.view.on("frame", function (_event) {
		graphLayer.activate();
		graphLayer.removeChildren();
		drawGridLines(numOfHBoxes, Paper.view.bounds);
	});
};

export default DrawGuideLine;
