/*
This file is used to display channel 1 and channel 2 waves on the left side of the 
screen on the oscilloscope page. This is done with the 
use of paperJS and AudioContext. We will look for the 
access to the users microphone, then for each (1/sampleRate) 
seconds we will pull in the current audio value. Theses values 
are placed in a buffer witch are then put on the graph to show 
the current value of buffer.
*/

import Paper from "paper";
import { setupWaveDataPopulation } from "./WaveData";
import { OscopeChannelWave } from "./OscopeChannelWave";
import { TriggerState } from "../enums/TriggerState";
import Channel from "../enums/Channel";

// Use Effects
let triggerState = TriggerState.eRising;
let saveFlag = false;
let timeDiv = 1;
let timeDiff = 0.5;
let voltDiff = 0;
let autoset = false;
let channel1 = new OscopeChannelWave(true, '#D00000');
let channel2 = new OscopeChannelWave(false, '#4169E1');
let fillDataArrayInterval: any;

export const setOscopeDrawWave = (val: boolean) => {channel1.setDrawing(val); channel2.setDrawing(val) }
export const setChannel1VoltDiv = (val: number) => channel1.setVoltDiv(val);
export const setChannel2VoltDiv = (val: number) => channel2.setVoltDiv(val);
export const setTimeDiv = (val: number) => timeDiv = val;
export const setTriggers = (time: number, volt: number) => { timeDiff = time; voltDiff = volt }
export const setYOffsets = (ch1: number, ch2: number) => { channel1.setYOffset(ch1); channel2.setYOffset(ch2) }
export const setOscopeAutoset = (val: boolean) => autoset = val;
export const setTriggerState = (val: TriggerState) => triggerState = val;
export const setOscopeSaveFlag = (val: boolean) => saveFlag = val;
export const setChannel1Enabled = (val: boolean) => channel1.setEnabled(val);
export const setChannel2Enabled = (val: boolean) => channel2.setEnabled(val);
export const setTriggerChannel = (val: Channel) => {
  channel1.setTriggerEnabled(val == Channel.e1); 
  channel2.setTriggerEnabled(val == Channel.e2); 
}

interface DrawOscopeCallbacks {
  changeChannelFrequency: (channel: Channel, frequency: number) => void,
  changeChannelVoltDiv: (channel: Channel, voltDiv: number) => void,
  changeTimeDiv: (timeDiv: number) => void,
  finishAutoset: () => void,
  finishSave: () => void,
}

export const drawOscopeWave = (callbacks: DrawOscopeCallbacks) => {
  
  clearInterval(fillDataArrayInterval);
  setupWaveDataPopulation(channel1, channel2, fillDataArrayInterval);

  // Creating new Paper objects will error if done globally
  // That is why thse lines are here instead of outside the function
  let waveLayer = new Paper.Layer();
  channel1.createPath();
  channel2.createPath();

  Paper.view.on('frame', function () {
    waveLayer.activate();
    const frequency1 = channel1.getFrequency();
    const frequency2 = channel2.getFrequency();
    callbacks.changeChannelFrequency(Channel.e1, Math.round(frequency1));
    callbacks.changeChannelFrequency(Channel.e2, Math.round(frequency2));
    const bothChannelsEnabled = channel1._enabled && channel2._enabled;

    if (autoset) {
      let greaterTimeDiv = -1;
      if (channel1._enabled) {
        const {xDiv: timeDiv1, yDiv: voltDiv1} = channel1.autoset(bothChannelsEnabled);
        callbacks.changeChannelVoltDiv(Channel.e1, voltDiv1);
        greaterTimeDiv = timeDiv1;
      }
      if (channel2._enabled) {
        const {xDiv: timeDiv2, yDiv: voltDiv2} = channel2.autoset(bothChannelsEnabled);
        callbacks.changeChannelVoltDiv(Channel.e2, voltDiv2);
        if (timeDiv2 > greaterTimeDiv) {
          greaterTimeDiv = timeDiv2;
        }
      }

      callbacks.changeTimeDiv(greaterTimeDiv);

      autoset = false;
      callbacks.finishAutoset();
    }
    if(saveFlag){
      channel1.save();
      channel2.save();
      saveFlag = false;
      callbacks.finishSave();
    }

    if (channel1._enabled) {
      channel1.draw(triggerState, timeDiv, voltDiff, timeDiff, bothChannelsEnabled);
    }
    if (channel2._enabled) {
      channel2.draw(triggerState, timeDiv, voltDiff, timeDiff, bothChannelsEnabled);
    }
  });
  

  Paper.view.on('resize', function (event: any) {
    waveLayer = new Paper.Layer();
    waveLayer.activate();
  });
};
