import React, {useRef, useState} from 'react';
import { isPlatform, IonContent, IonPage, IonButton } from '@ionic/react';
import { clamp } from "../utils/MathUtils";

import './Pages.css';
import OscilloscopeScope from '../components/scopes/OscilloscopeScope';
import WakeLock from '../components/WakeLock';
import PageHeader from '../components/PageHeader';
import FullscreenDisplayButton from '../buttons/FullscreenDisplayButton';
import FullscreenExitButton from '../buttons/FullscreenExitButton';
import WaveInfoDisplay, { WaveInfoDisplayElement } from '../components/WaveInfoDisplay';
import SelectFromOptionsPopover from '../components/SelectFromOptionsPopover';
import { TriggerState } from '../enums/TriggerState';
import Channel from '../enums/Channel';
import SettingsProperty from "../enums/SettingsProperty";
import { serialConnection } from '../components/Serial';

const OScope: React.FC = () => {
  const name = "Oscilloscope";
  const timeUnitDiv = 453.6;
  const voltDivStep = 0.1;
  const maxVoltDiv = 5;
  const minVoltDiv = 0.1;
  const triggerOptions = [TriggerState.eRising, TriggerState.eFalling, TriggerState.eSingleTrigger];

  // TODO: Set playing to false when changing hardware scaler
  // For more information contact @Root3287
  const [playing, setPlaying] = useState(true);
  const [channel1Flag, setChannel1Flag] = useState(true);
  const [channel2Flag, setChannel2Flag] = useState(false);
  const [triggerChannel, setTriggerChannel] = useState(Channel.e1);
  const [triggerState, setTriggerState] = useState(TriggerState.eRising);
  const [flag, setFlag] = useState(true);
  const [fullscreenFlag, setFullscreenFlag] = useState(true);
  const [displayFlag, setDisplayFlag] = useState(true);
  const [channel1VoltDiv, setChannel1VoltDiv] = useState(.5);
  const [channel2VoltDiv, setChannel2VoltDiv] = useState(.5);
  const [timeStart, setTimeStart] = useState(1);
  const [channel1Frequency, setChannel1Frequency] = useState(440);
  const [channel2Frequency, setChannel2Frequency] = useState(440);
  const [cursorFlag, setCursorFlag] = useState(false);
  const [autoset, setAutoset] = useState(false);
  const [timeDiff, setTimeDiff] = useState(0);
  const [voltDiff, setVoltDiff] = useState(0);
  const [saveFlag, setSaveFlag] = useState(false);
  const [triggerPopoverHidden, setTriggerPopoverHidden] = useState(true);

  function changeChannel1Frequency(frequency : number){
    setChannel1Frequency(frequency);
  }

  const [channel1BufferSize, setChannel1BufferSize] = useState(8192);
  const [channel2BufferSize, setChannel2BufferSize] = useState(8192);

  function changeChannelFrequency(channel: Channel, frequency : number){
    if(channel === Channel.e1)
      setChannel1Frequency(frequency);
    if(channel === Channel.e2)
      setChannel2Frequency(frequency);
  }

  function changeCursorDiff(timeDiff: number, voltDiff: number){
    setTimeDiff(timeDiff);
    setVoltDiff(voltDiff);
  }

  function increaseSingleChannelVoltDiv() {
    if (channel1Flag && channel2Flag) {
      // Both channels are active, so show sets of volt/div for both channels.
      showDualVoltageControls();
      return;
    }
    increaseChannel1VoltDiv();
    increaseChannel2VoltDiv();
  }

  function decreaseSingleChannelVoltDiv() {
    if (channel1Flag && channel2Flag) {
      // Both channels are active, so show sets of volt/div for both channels.
      showDualVoltageControls();
      return;
    }
    decreaseChannel1VoltDiv();
    decreaseChannel2VoltDiv();
  }

  function increaseChannel1VoltDiv() {
    if (!channel1Flag) return;
    setChannel1VoltDiv(clamp(channel1VoltDiv+voltDivStep, minVoltDiv, maxVoltDiv));
  }

  function decreaseChannel1VoltDiv() {
    if (!channel1Flag) return;
    setChannel1VoltDiv(clamp(channel1VoltDiv-voltDivStep, minVoltDiv, maxVoltDiv));
  }

  function increaseChannel2VoltDiv() {
    if (!channel2Flag) return;
    setChannel2VoltDiv(clamp(channel2VoltDiv+voltDivStep, minVoltDiv, maxVoltDiv));
  }

  function decreaseChannel2VoltDiv() {
    if (!channel2Flag) return;
    setChannel2VoltDiv(clamp(channel1VoltDiv-voltDivStep, minVoltDiv, maxVoltDiv));
  }

  function changeChannelVoltDiv(channel: Channel, voltDiv : number) {
    let newVoltDiv = clamp(minVoltDiv, voltDiv, maxVoltDiv);
    // Round to nearest .1
    newVoltDiv = Math.round(newVoltDiv * 10) / 10;

    if(channel === Channel.e1)
      setChannel1VoltDiv(newVoltDiv);
    if(channel === Channel.e2)
      setChannel2VoltDiv(newVoltDiv);
  }

  function changeTimeInc() {
    if (timeStart >= 80) return;

    setTimeStart((prev) => {
      let nextPower = Math.pow(2, Math.ceil(Math.log2(prev * 1.0001))); // Tiny offset to handle exact powers
      return nextPower <= 80 ? nextPower : prev; // Ensure it stays within limits
    });
  }

  function changeTimeDec() {
    if (timeStart <= 2 ** -6) return; // Prevent going below 0.015625

    setTimeStart((prev) => {
      let nextLowerPower = Math.pow(2, Math.floor(Math.log2(prev / 1.0001))); // Tiny offset to handle exact powers
      return nextLowerPower >= 2 ** -4 ? nextLowerPower : prev; // Ensure lower limit
    });
  }

  function changeTimeDiv(timeDiv : number) {
    setTimeStart(timeDiv)
  }

  function togglePlaying(){
    setPlaying(!playing);
  }

  function changeDisplayFlag(){
    setDisplayFlag(!displayFlag);
  }

  function changeFullscreenFlag(){
    setFullscreenFlag(!fullscreenFlag);
  }

  function changeCursorFlag(){
    setCursorFlag(!cursorFlag)
  }

  function toggleSaveButton() {
    // Don't allow toggling off via button.
    setSaveFlag(true);
  }

  function saveFinish() {
    setSaveFlag(false);
  }

  function toggleAutosetButton() {
    // Don't allow toggling off via button.
    setAutoset(true);
  }

  function autosetFinish() {
    setAutoset(false);
  }

  function popoverTriggerMenuSet(value: string | undefined) {
    setTriggerPopoverHidden(true);
    if(value === undefined) return;
    switch (value) {
      case TriggerState.eFalling.toString():
        setTriggerState(TriggerState.eFalling);
        break;
      case TriggerState.eRising.toString():
        setTriggerState(TriggerState.eRising);
        break;
      case TriggerState.eSingleTrigger.toString():
        setTriggerState(TriggerState.eSingleTrigger);
        break;
    }
  }

  function calculateTime(){
    return (timeStart*.4536*10*timeDiff).toFixed(4)
  }
  function calculateChannel1Voltage(){
     return (channel1VoltDiv*8*voltDiff).toFixed(1)
  }
  function calculateChannel2Voltage(){
    return (channel2VoltDiv*8*voltDiff).toFixed(1)
 }
  function calculateTimeDivision(){
     return (timeStart*.4536).toFixed(4)
  }

  function channel1Info() {
    const elements: WaveInfoDisplayElement[] = [
      { label: 'Frequency', value: channel1Frequency.toString(), unit: 'Hz', isCursor: false},
      { label: 'Time Division', value: calculateTimeDivision(), unit: 'ms', isCursor: false},
      { label: 'Voltage Division', value: channel1VoltDiv.toFixed(1), unit: 'V', isCursor: false},
      { label: 'Voltage', value: calculateChannel1Voltage(), unit: 'V', isCursor: true},
      { label: 'Time', value: calculateTime(), unit: 'ms', isCursor: true},
    ];
    return elements;
  }

  function channel2Info() {
    const elements: WaveInfoDisplayElement[] = [
      { label: 'Frequency', value: channel2Frequency.toString(), unit: 'Hz', isCursor: false},
      { label: 'Time Division', value: calculateTimeDivision(), unit: 'ms', isCursor: false},
      { label: 'Voltage Division', value: channel2VoltDiv.toFixed(1), unit: 'V', isCursor: false},
      { label: 'Voltage', value: calculateChannel2Voltage(), unit: 'V', isCursor: true},
      { label: 'Time', value: calculateTime(), unit: 'ms', isCursor: true},
    ];
    return elements;
  }

  function toggleChannel1Button() {
    serialConnection.setAnalogChannelEnable(!channel1Flag, channel2Flag);
    setChannel1Flag(!channel1Flag);
  }

  function toggleChannel2Button() {
    serialConnection.setAnalogChannelEnable(channel1Flag, !channel2Flag);
    setChannel2Flag(!channel2Flag);
  }

  const dualChannelVoltageControls: any = useRef(null);

  function showDualVoltageControls() {
    // This is being set to flex because it is set to "none" when it is hidden
    dualChannelVoltageControls.current.style.display = "flex"
    // This is the fade in animation after you press a volt/div button
    dualChannelVoltageControls.current.style.opacity = "0";
    requestAnimationFrame(() => {
      dualChannelVoltageControls.current.style.opacity = "1";
    });
  }

  function hideDualVoltageControls() {
    // This is for the fade out animation after you hit the x button.
    // 500 is the number of ms for the animation to complete
    dualChannelVoltageControls.current.style.opacity = "0";
    setTimeout(() => {
      dualChannelVoltageControls.current.style.display = "none";
    }, 500);
  }

  function onPageHeaderSettingUpdate(property: SettingsProperty, value: any){
    // Handle the state changes.
    // Also where we can also send the Serial Packet to change hardware board scaler.
  }

  return (
    <IonPage>
      <PageHeader
        name={name}
        hidden={!fullscreenFlag}
        isConnectHidden={false}
        onFullscreenClick={changeFullscreenFlag}
        onSettingsChange={onPageHeaderSettingUpdate}
        tutorialPath={"OScope"}
      />

      <IonContent fullscreen scrollY={false} color="secondary">

      <div className="full-screen">
        <FullscreenExitButton hidden={fullscreenFlag} onClick={changeFullscreenFlag}/>
        <FullscreenDisplayButton hidden={fullscreenFlag} onClick={changeDisplayFlag}/>
        <div className={isPlatform("mobile") ? "display-div-fullscreen-mobile" : "display-div-fullscreen"}>
          <WaveInfoDisplay
            hidden={displayFlag || fullscreenFlag || !channel1Flag}
            isFullscreen={true}
            cursorFlag={cursorFlag}
            elements={channel1Info()}
            color={"#D00000"}
          />
          <WaveInfoDisplay
            hidden={displayFlag || fullscreenFlag || !channel2Flag}
            isFullscreen={true}
            cursorFlag={cursorFlag}
            elements={channel2Info()}
            color={"#4169E1"}
          />
        </div>

	{/* Makes it so the screen doesn't turn off when on the oscope page */}
        <WakeLock enabled={true} />

        {/* The graph element for the oscope */}
        <div className={isPlatform("mobile") ? (fullscreenFlag ? "oscilloscope-div" : "oscilloscope-div-full") :
                                                                     (fullscreenFlag ? "oscilloscope-div-web" : "oscilloscope-div-full-web")}>
          <OscilloscopeScope
            className="graph"
            isFullscreen={fullscreenFlag}
            pausePlay = {playing}
            voltageDiv = {0.5}
            autoset = {autoset}
            timeDiv = {timeStart}
            // triggerEnable = { false }
            cursorEnable = { cursorFlag }
            save = { saveFlag }
            triggerState = { triggerState }
            channel1VoltDiv = {channel1VoltDiv}
            channel2VoltDiv = {channel2VoltDiv}
            channel1Enabled = {channel1Flag}
            channel2Enabled = {channel2Flag}
            cursorChangeCallback = {changeCursorDiff}
            channelFrequencyChangeCallback = {changeChannelFrequency}
            changeTimeDiv = {changeTimeDiv}
            voltageDivChangeCallback = {changeChannelVoltDiv}
            autosetFinishCallback = {autosetFinish}
            saveFinishCallback = {saveFinish}
            triggerChannel = {triggerChannel}
            // XAxisDivChangeCallback = {() => {}}
          />
          <div className={fullscreenFlag ? "under-graph-div" : "under-graph-div-full"}>
            <div>
              <div className="under-graph-background">
                <IonButton className="graph-button" mode="ios" onClick = {() => toggleChannel1Button()} fill={channel1Flag ? "solid" : "clear"} color={channel1Flag ? "primary" : "tertiary"} hidden={!fullscreenFlag} data-testid="channel-button">
                  <div>
                    Channel 1
                  </div>
                </IonButton>
                <IonButton className="graph-button" mode="ios" onClick = {() => toggleChannel2Button()} fill={channel2Flag ? "solid" : "clear"} color={channel2Flag ? "channel2" : "tertiary"} hidden={!fullscreenFlag} data-testid="channel-button">
                  <div>
                    Channel 2
                  </div>
                </IonButton>
              </div>
            </div>
            <div>
              <div className="under-graph-background">
                <IonButton className="graph-button" mode="ios" onClick = {() => setTriggerChannel(Channel.e1)} fill={triggerChannel === Channel.e1 ? "solid" : "clear"} color={triggerChannel === Channel.e1 ? "primary" : "tertiary"} hidden={!fullscreenFlag}>
                  <div>
                    Trigger Ch 1
                  </div>
                </IonButton>
                <IonButton className="graph-button" mode="ios" onClick = {() => setTriggerChannel(Channel.e2)} fill={triggerChannel === Channel.e1 ? "clear" : "solid"} color={triggerChannel === Channel.e1 ? "tertiary" : "channel2"} hidden={!fullscreenFlag}>
                  <div>
                    Trigger Ch 2
                  </div>
                </IonButton>
              </div>
            </div>
          </div>
        </div>

        {/* The buttons on the right hand side of the graph */}
        <div className={isPlatform("mobile") ? (fullscreenFlag ? "side-data" : "side-data-hidden") :
                                               (fullscreenFlag ? "side-data-web" : "side-data-hidden")}>
          <div className="first-row-div"> {/* First row of UI buttons */}
            <IonButton className="utility-buttons" mode="ios" onClick = {() => toggleAutosetButton()} color={autoset ? "primary" : "light"}>
                <div>
                  Auto
                </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => increaseSingleChannelVoltDiv()} color="tertiary">
              <div>
                Volt/Div
                <div>
                  +{voltDivStep}V
                  </div>
              </div>
            </IonButton>
            <IonButton className="utility-buttons" mode="ios"  onClick = {() => changeCursorFlag()} color={cursorFlag ? "primary" : "light"}>
              <div>
                Cursors
              </div>
            </IonButton>
          </div>

          <div className="second-row-div"> {/* Second row of UI buttons */}
          <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => changeTimeDec()} color="tertiary">
              <div>
                Time/Div
                <div>
                  -{timeUnitDiv}us
                </div>
              </div>
            </IonButton>
            <IonButton id = "pause-play-button" className="pause-play-button" mode="ios" onClick = {() => togglePlaying()} color={playing ? "primary" : "tertiary"}>
              <div>
                <img className="pause-play-img" src={process.env.PUBLIC_URL + (!playing ? "/assets/pause.png" : "/assets/playwhite.png")} alt="" ></img>
                <div>{playing ? "Playing" : "Paused" }</div>
              </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => changeTimeInc()} color="tertiary">
              <div>
                Time/Div
                <div>
                  +{timeUnitDiv}us
                </div>
              </div>
            </IonButton>
          </div>

          <div className="third-row-div"> {/* Third row of UI buttons */}
            <IonButton className="utility-buttons" mode="ios" onClick = {() => toggleSaveButton()} color={saveFlag ? "primary" : "light"} data-testid="save-button">
                <div>
                  Save
                </div>
            </IonButton>
            <IonButton className="voltage-time-division-button" mode="ios" onClick = {() => decreaseSingleChannelVoltDiv()}  color="tertiary" data-testid="volt-div-neg-button">
              <div>
                Volt/Div
                <div>
                  -{voltDivStep}V
                </div>
              </div>
            </IonButton>
            <IonButton className="utility-buttons" mode="ios" color="light" onClick={() => setTriggerPopoverHidden(false)} data-testid="trigger-button">
              <div>
                Trigger<br />Menu
              </div>
            </IonButton>
          </div>

          {/* Hidden voltage controls for dual channels. */}
          <div className="dual-channel-voltage" ref={dualChannelVoltageControls}>
            <div className="dual-channel-voltage-close-button" onClick={() => hideDualVoltageControls()}>
              <svg xmlns="http://www.w3.org/2000/svg" className="icon icon-tabler icon-tabler-x" width="20" height="20" viewBox="0 0 24 24" strokeWidth="1.5" stroke="#F5F5F5" fill="none" strokeLinecap="round" strokeLinejoin="round">
                <path stroke="none" d="M0 0h24v24H0z" fill="none"></path>
                <path d="M18 6l-12 12"></path>
                <path d="M6 6l12 12"></path>
              </svg>
            </div>
            <div className="channel-voltage-controls">
              <IonButton className="dual-channel-voltage-time-division-button" mode="ios" onClick = {() => increaseChannel1VoltDiv()} color="primary" data-testid="volt-div-neg-button">
                <div>
                  Volt/Div
                  <div>
                    +{voltDivStep}V
                  </div>
                </div>
              </IonButton>
              <IonButton className="dual-channel-voltage-time-division-button" mode="ios" onClick = {() => decreaseChannel1VoltDiv()} color="primary" data-testid="volt-div-neg-button">
                <div>
                  Volt/Div
                  <div>
                    -{voltDivStep}V
                  </div>
                </div>
              </IonButton>
            </div>
            <div className="channel-voltage-controls">
              <IonButton className="dual-channel-voltage-time-division-button" mode="ios" onClick = {() => increaseChannel2VoltDiv()} color="channel2" data-testid="volt-div-neg-button">
                <div>
                  Volt/Div
                  <div>
                    +{voltDivStep}V
                  </div>
                </div>
              </IonButton>
              <IonButton className="dual-channel-voltage-time-division-button" mode="ios" onClick = {() => decreaseChannel2VoltDiv()} color="channel2" data-testid="volt-div-neg-button">
                <div>
                  Volt/Div
                  <div>
                    -{voltDivStep}V
                  </div>
                </div>
              </IonButton>
            </div>
          </div>
          <div className="display-div">
            {/* Channel 1 Info */}
            <WaveInfoDisplay
              hidden={!fullscreenFlag || !channel1Flag}
              isFullscreen={false}
              cursorFlag={cursorFlag}
              elements={channel1Info()}
              color={"#D00000"}
            />
            {/* Channel 2 Info */}
            <WaveInfoDisplay
              hidden={!fullscreenFlag || !channel2Flag}
              isFullscreen={false}
              cursorFlag={cursorFlag}
              elements={channel2Info()}
              color={"#4169E1"}
            />
          </div>
        </div>
      </div>
      {/* Trigger Menu Popover */}
      <SelectFromOptionsPopover hidden={triggerPopoverHidden} buttonLabels={triggerOptions} onButtonPressed={popoverTriggerMenuSet}/>

      </IonContent>
    </IonPage>
  );
};

export default OScope;
