import { useRef, useEffect, useCallback } from 'react';
import Paper from 'paper';
import drawGuideLine, { setNumChannels } from '../DrawGuideLine';
import drawCursors, { setCursorFlag } from '../cursors';
import {
    setPlaying,
    setZoomLevel,
    setNumberOfSamples,
    setSampleRate,
    setCurrentLeft,
    setCurrentRight,
    callReDraw,
    drawLogicAnalyzerWave,
    setDecodingState,
} from '../DrawLogicAnalyzerWave';
import { isPlatform } from '@ionic/react';
import DecodingMode from '../../enums/DecodingMode';

interface LogicAnalyzerScopeProperty {
    className: string;
    sampleCount: number;
    sampleRate: number;
    isFullscreen: boolean;
    playingFlag: boolean;
    setPlaying: (playing: boolean) => void;
    cursorChangeCallback: (timeDiff: number, voltDiff: number) => void;
    cursorFlag: boolean;
    zoomLevel: number;
    changeZoom: (dir: number) => void;
    sampleLeft: number;
    sampleRight: number;
    changeScroll: (dir: number) => void;
    decodingMode: DecodingMode;
    decodingChannel: number;
};

const LogicAnalyzerScope = (props: LogicAnalyzerScopeProperty) => {
    const canvasRef: any = useRef(null);
    const renderFrame: any = useRef(null);
    const initialClassName = window.innerHeight < 500 ? "logicgraph-mobile" : props.className;

    const handleVerticalScroll = useCallback((event: any) => {
        event.preventDefault();

        const direction = event.deltaY > 0 ? 1 : -1;
        props.changeZoom(direction);
    }, [props]);

    const handleHorizontalScroll = useCallback((event: any) => {
        event.preventDefault();

        const delta = event.deltaX;
        props.changeScroll(delta > 0 ? 1 : -1);
    }, [props]);

    useEffect(() => {
        setNumberOfSamples(props.sampleCount);
    }, [props.sampleCount]);

    useEffect(() => {
        setSampleRate(props.sampleRate);
    }, [props.sampleRate]);

    useEffect(() => {
        setCurrentLeft(props.sampleLeft)
    }, [props.sampleLeft]);

    useEffect(() => {
        setCurrentRight(props.sampleRight)
    }, [props.sampleRight]);

	useEffect(() => {
        setZoomLevel(props.zoomLevel);
	}, [props.zoomLevel]);

    useEffect(() => {
        const channels = (props.decodingMode === DecodingMode.eDisabled) ? 8 : 9;
        setNumChannels(channels);
    }, [props.decodingMode]);

    useEffect(() => {
        setDecodingState(props.decodingMode, props.decodingChannel);
    }, [props.decodingMode, props.decodingChannel])

    useEffect(() => {
        const canvas = canvasRef.current;

        const handleWheelEvent = (event: any) => {
            const isVertical = Math.abs(event.deltaY) > Math.abs(event.deltaX);

            if (isVertical) {
                handleVerticalScroll(event);
            } else {
                handleHorizontalScroll(event);
            }
        };

        if (canvas) {
            canvas.addEventListener('wheel', handleWheelEvent, { passive: false });

            return () => canvas.removeEventListener('wheel', handleWheelEvent);
        }
    }, [handleVerticalScroll, handleHorizontalScroll]);

    const animate = () => {
        if (!canvasRef.current || canvasRef.current.clientWidth === 0) {
            renderFrame.current = requestAnimationFrame(animate);
            return;
        }

        const canvas = canvasRef.current;

        Paper.setup(canvas);
        new Paper.Project(canvas);

        drawGuideLine();

        drawLogicAnalyzerWave(props.setPlaying);

        drawCursors(props.cursorChangeCallback);

        (Paper.view as any).draw();
    };

    useEffect(() => {
        renderFrame.current = requestAnimationFrame(animate);

        return () => {
            cancelAnimationFrame(renderFrame.current);
        };
    }, []);

    useEffect(() => {
        if (!Paper.view) return;
        Paper.view.viewSize = isPlatform("mobile") ?
            new Paper.Size(canvasRef.current.clientWidth, canvasRef.current.clientHeight) :
            new Paper.Size(canvasRef.current.clientWidth * 2, canvasRef.current.clientHeight * 2);
        Paper.view.emit('resize', {});
        callReDraw();
    }, [props.isFullscreen]);

    useEffect(() => {
        setPlaying(props.playingFlag);
    }, [props.playingFlag]);

    useEffect(() => {
        setCursorFlag(props.cursorFlag, false);
    }, [props.cursorFlag]);

    return <canvas ref={canvasRef} className={initialClassName} data-paper-resize="true" />
};

export default LogicAnalyzerScope;