import Paper from "paper";
import exportCSV from "./exportCSV";
import { WindowFunction } from "../enums/WindowFunction";
import { serialConnection } from "./Serial";
let fft = require('fft-js').fft;
let windowing = require('fft-windowing');

export class SpectrumChannelWave {
    _enabled: boolean;
    _bufferSize: number = 4096;
    _data: Float32Array = new Float32Array(this._bufferSize);
    _channelSubsetData = new Float32Array(this._bufferSize);
    _fftSize = this._bufferSize;
    _freqPerPoint = serialConnection.getSampleRate() / this._fftSize;
    _amountOfPoints: number = 200;
    _path: paper.Path | undefined;
    _drawing: boolean = true;
    _color: string;

    constructor (enabled: boolean, color: string) {
        this._enabled = enabled;
        this._color = color;
    }

    setEnabled (enabled: boolean) {
        this._enabled = enabled;
        if (!this._path) return;
        this._path.visible = enabled;
    }

    setData (data: Float32Array) {
        if (!this._drawing) return;
        this._data = data;
    }

    setDrawing (drawing: boolean) {
      this._drawing = drawing;
    }

    createPath () {
      this._path = new Paper.Path(
        {strokeColor: this._color, visible: this._enabled}
      );
    }

    /**
     * Resets the points to the x axis
     * @returns
     */
    init () {
        if (!this._path) return;
        this._path.removeSegments();
        // Place points on the x axis so then we only modify the y coordinate when we draw
        for (let i = 0; i <= this._amountOfPoints; i++) {
          const xScreen = (i / this._amountOfPoints) * Paper.view.size.width;
          const yScreen = (1 / 2) * Paper.view.size.height;
          const point = new Paper.Point(xScreen, yScreen);
          this._path.add(point);
        }
    }

    save () {
      if (!this._enabled) return;
      exportCSV(this._channelSubsetData);
    }

    /**
     * Called if autoset button is pressed on the ui
     * @returns The frequency that will become the center frequency if only this channel is enabled
     */
    getPeakFrequency () {
      // Find the highest peak within channel 1.
      let maxDecibels = Number.NEGATIVE_INFINITY;
      let maxDecibelsIdx = Number.NEGATIVE_INFINITY;
      for (let i = 0; i < this._channelSubsetData.length; i++) {
        if (this._channelSubsetData[i] > maxDecibels) {
          maxDecibels = this._channelSubsetData[i];
          maxDecibelsIdx = i;
        }
      }
      const peakFrequency = maxDecibelsIdx * this._freqPerPoint;
      return peakFrequency;
    }

    /**
     * Sends inputArray through specified windowFunction and performs a Fast Fourier Transform on the result
     * @param inputArray an array of size: bufferSize
     * @param windowFunction The window function set by the ui
     * @returns the array that will be drawn to the graph
     */
    performFFT (inputArray: Float32Array, windowFunction: WindowFunction) {

      let windowedArray = inputArray;
      switch (windowFunction) {
        case (WindowFunction.eRectangle):
            // Rectangle window function basically means no windowing
            break;
        case (WindowFunction.eHanning):
            windowedArray = windowing.hann(windowedArray);
            break;
        case (WindowFunction.eGaussian):
            windowedArray = windowing.gaussian(windowedArray);
            break;
        case (WindowFunction.eHamming):
            windowedArray = windowing.hamming(windowedArray);
            break;
        case (WindowFunction.eKaiser):
            windowedArray = windowing.kaiser(windowedArray);
            break;
        case (WindowFunction.eFlatTop):
            windowedArray = windowing.flat_top(windowedArray);
            break;
      }

      let response = fft(windowedArray);
      let fftArray = new Float32Array(windowedArray.length);
      // Populates array with the magnitude of the FFT result
      let k = 1;
      let n = fftArray.length;
      for (let i = 0; i < n; i++) {
        let magnitude = Math.sqrt( Math.pow(response[i][0], 2) + Math.pow(response[i][1], 2) );
        // This math converts the magnitude into decibels
        fftArray[i] = 20 * Math.log10( Math.abs((k/n) * magnitude) );
        k = Math.sqrt(2)
      }
      return fftArray;
    }

   /**
    * If newSize is half the size of fullArray then the subsetArray will contain every other data from fullArray
    * @param fullArray an array of size: bufferSize
    * @param newSize the fft size set by the ui
    * @returns an array of size: newSize that contains data from fullArray
    */
    performSubset (fullArray: Float32Array, newSize: number) {
      let subsetArray = new Float32Array(newSize);
      let fullSize = fullArray.length;
      let iIncrement = Math.ceil(fullSize/newSize);
      let i = 0;
      let j = 0;
      while (i < fullSize) {
        subsetArray[j] = fullArray[i];
        j++;
        i += iIncrement;
      }
      return subsetArray;
    }

    /**
     * Sets the y coordinate of points on the graph
     * @param center The center frequency set by the ui
     * @param decibelsDiv The amount of decibels a block of the graph represents
     * @param freqDiv The amount of Hz a block of the graph represents
     * @param fftSize The fft size set by the ui
     * @param windowType The window function set by the ui
     * @returns
     */
    draw (center: number, decibelsDiv: number, freqDiv: number, fftSize: number, windowType: WindowFunction) {
        if (this._path === undefined) return;
        const height = Paper.view.size.height;
        this._freqPerPoint = serialConnection.getSampleRate() / fftSize;
        let fftDataArray = new Float32Array(this._bufferSize);

        // Copy over the dataArray so we don't have bug
        for (let i = 0; i < this._data.length; i++) {
          fftDataArray[i] = this._data[i];
        }
        // Mobile Only
        // audioinput data only contains 4095 values
        // Duplicate the last value to get 4096
        if (this._data.length === 4095)
          fftDataArray[fftDataArray.length - 1] = this._data[this._data.length - 1];

        // FFT is performed over the entire array and then only a subset is graphed based on the fft size
        // This might be incorrect the more I think about it, maybe the subset should happen first
        fftDataArray = this.performFFT(fftDataArray, windowType);
        let subsetFFTDataArray = this.performSubset(fftDataArray, fftSize);
        this._channelSubsetData = subsetFFTDataArray;

        // Graph 200 points around the center frequency
        let centerIdx = Math.floor(center / this._freqPerPoint);
        let leftIdx = centerIdx - (100 * freqDiv);

        // Get heights of canvas elements
        const divHeight = height / 8;
        const zeroHeight = height / 4;

        for (let i = 0; i <= this._amountOfPoints; i++) {
          let bufferPoint = subsetFFTDataArray[freqDiv * i + leftIdx]; // freqDiv is a number between [1-20]

          // Flip sign of bufferPoint because more positive numbers show up lower on the canvas
          bufferPoint = bufferPoint * -1;
          bufferPoint /= decibelsDiv;

          // Set the y coordinate of the ith segment point
          let segment = this._path.segments[i];
          segment.point.y = zeroHeight + (divHeight * bufferPoint);
        }
    }
  }
