import { BleClient } from "@capacitor-community/bluetooth-le";
import { isPlatform } from "@ionic/core";
import PacketType from "../enums/PacketType";
import TriggerStateLA from "../enums/TriggerStateLA";

const topVoltage = 5;
const dataBits = 12;
const topValueFromADC = (Math.pow(2, dataBits) - 1);

function packetToBytes(packet) {
    const size = packet.data.length + 2;
    const encodedSize = (size / 2) - 1;
    const type = packet.type;
    return new Uint8Array([encodedSize, type, ...packet.data]);
}

const MODE_ANALOG = 1;
const MODE_DIGITAL = 2;

class SerialConnection {
    constructor() {
      this.isConnected = false;
      this.hardwareScaler = 1;
      this.analogChannelMask = 1;
      this.mode = null;
      this.buffer = new Uint8Array();
      this.readQueue = [];
      this.writePendingTimeout = null;
      this.writePending = null;
      this.writeQueue = [];
      this.triggerState = TriggerStateLA.eOff;
      this.triggerChannel = 0;
    }

    // To extend this class implement these three functions and call appendBuffer when needed
    async connect() { return false; }
    async sendPacketImpl() {}
    async disconnect() {}

    reset() {
        this.isConnected = false;

        this.buffer = new Uint8Array();

        if (this.writePendingTimeout) {
            clearTimeout(this.writePendingTimeout)
            this.writePendingTimeout = null;
        }

        if (this.writePending) {
            this.writePending.reject("Disconnected");
            this.writePending = null;
        }

        this.readQueue.forEach((request) => {request.reject("Disconnected")});
        this.readQueue = [];

        this.writeQueue.forEach((request) => {request.reject("Disconnected")});
        this.writeQueue = [];
    }

    async appendBuffer(dataView) {
        const data = new Uint8Array(dataView.buffer);

        let newBuffer = new Uint8Array(data.length + this.buffer.length);
        newBuffer.set(this.buffer, 0);
        newBuffer.set(data, this.buffer.length);
        this.buffer = newBuffer;

        await this.#handleReadQueue();
    }

    async #handleReadQueue() {
        if (this.buffer.length <= 0) {
            return;
        }

        const size = (this.buffer[0] + 1) * 2;
        if (this.buffer.length < size) {
            return;
        }

        const type = this.buffer[1];

        let data = null;
        if (size > 2) {
            data = this.buffer.slice(2, size);
        }

        this.buffer = this.buffer.slice(size);

        if (type === PacketType.Ack && this.writePending) {
            clearTimeout(this.writePendingTimeout);
            this.writePending.resolve({type, data});
            this.writePending = null;
            await this.#handleWriteQueue();
        } else {
            await this.sendPacketImpl({
                type: PacketType.Ack,
                data: new Uint8Array()
            });

            this.readQueue.forEach((request) => {
                request.resolve({type, data});
            });

            this.readQueue = [];
        }
    }

    async #resendPacket() {
        if (this.writePending === null) {
            return;
        }
        this.writePending.tries += 1;
        if (this.writePending.tries > 5) {
            this.disconnect();
        } else {
            await this.sendPacketImpl(this.writePending.packet);
            this.writePendingTimeout = setTimeout(this.#resendPacket.bind(this), 1000);
        }
    }

    async #handleWriteQueue() {
        if (this.writePending !== null || this.writeQueue.length === 0) {
            return;
        }

        this.writePending = this.writeQueue.shift();
        await this.#resendPacket();
    }

    async nextPacket() {
        const p = new Promise((resolve, reject) => {
            this.readQueue.push({resolve, reject});
        });
        await this.#handleReadQueue();
        return p;
    }

    async sendPacket(packet) {
        const p = new Promise((resolve, reject) => {
            this.writeQueue.push({resolve, reject, packet, tries: 0});
        });
        await this.#handleWriteQueue();
        return p;
    }

    getSampleRate() {
        if (this.isConnected && this.mode === MODE_ANALOG) {
            let channels = 0;

            if ((this.analogChannelMask & 1) !== 0) {
                channels += 1;
            }

            if ((this.analogChannelMask & 2) !== 0) {
                channels += 1;
            }

            if (channels !== 0) {
                return 1000000 / (channels * this.hardwareScaler);
            }
        } else if (this.isConnected && this.mode === MODE_DIGITAL) {
            return 1000000 / this.hardwareScaler;
        }

        // Default to audio sample rate
        return 44100;
    }

    async updateConfig() {
        if (this.isConnected && this.mode === MODE_ANALOG) {
            await this.analogConfig();
        } else if (this.isConnected && this.mode === MODE_DIGITAL) {
            await this.digitalConfig();
        }
    }

    async setHardwareScaler(scaler) {
        if (!scaler) {
            return;
        }

        this.hardwareScaler = scaler;
        await this.updateConfig();
    }

    async setLATrigger(state, channel) {
        if (!state || !channel) {
            return;
        }

        this.triggerState = state;
        this.triggerChannel = channel;
        await this.updateConfig();
    }

    async setAnalogChannelEnable(channel1En, channel2En) {
        let mask = 0;

        if (channel1En) {
            mask |= 1;
        }

        if (channel2En) {
            mask |= 2;
        }

        this.analogChannelMask = mask;
        await this.updateConfig();
    }

    setAnalogMode() {
        this.mode = MODE_ANALOG;
        this.updateConfig();
    }

    setDigitalMode() {
        this.mode = MODE_DIGITAL;
        this.updateConfig();
    }

    async analogConfig() {
        const b1 = this.hardwareScaler & 0xFF;
        const b2 = (this.hardwareScaler >> 8) & 0xFF;
        const b3 = (this.hardwareScaler >> 16) & 0xFF;

        await this.sendPacket({
            type: PacketType.ScopeConfig,
            data: [this.analogChannelMask, b1, b2, b3]
        });
    }

    async analogRead(channelOne, channelTwo) {
        if (this.mode !== MODE_ANALOG) {
            return;
        }

        let channelOneIndex = 0;
        let channelTwoIndex = 0;

        while ((channelOneIndex < channelOne.length) && (channelTwoIndex < channelTwo.length)) {
            if (!this.isConnected) {
                break;
            }

            let packet;
            try {
                packet = await this.nextPacket();
            } catch(error) {
                console.log(error);
                break;
            }

            if (!packet) {
                console.log("Failed to read next packet");
                break;
            }

            if (packet.type !== PacketType.ScopeSample) {
                console.log("Got unexpected packet during read ", packet);
                break;
            }

            let i = 0;
            while (i < packet.data.length) {
                let value = packet.data[i];
                value = value | (packet.data[i + 1] << 8);
                i += 2;

                const channel = value & 0x8000;
                value = value & 0x0FFF;

                const volts = topVoltage * (value / topValueFromADC);
                const trueVolts = volts - (topVoltage / 2);

                if (channel === 0) {
                    channelOne[channelOneIndex] = trueVolts;
                    channelOneIndex++;
                } else {
                    channelTwo[channelTwoIndex] = trueVolts;
                    channelTwoIndex++;
                }
            }
        }
    }

    async digitalConfig() {
        let type = 0;
        if (this.triggerState === TriggerStateLA.eRising) {
            type = 1;
        } else if (this.triggerState === TriggerStateLA.eFalling) {
            type = 2;
        }

        let channel = this.triggerChannel;
        channel = channel ? channel : 0;
        channel = 1 << channel;

        // Clock Divide 4 bytes
        const b1 = this.hardwareScaler & 0xFF;
        const b2 = (this.hardwareScaler >> 8) & 0xFF;
        const b3 = (this.hardwareScaler >> 16) & 0xFF;
        const b4 = (this.hardwareScaler >> 24) & 0xFF;

        await this.sendPacket({
            type: PacketType.DigitalConfig,
            data: [type, channel, b1, b2, b3, b4]
        });
    }

    async digitalRead() {
        if (this.mode !== MODE_DIGITAL) {
            return;
        }

        const packet = await this.nextPacket();
        if (!packet || packet.type !== PacketType.DigitalSample || !packet.data) {
            return null;
        }

        return packet.data;
    }

    async sampleStop() {
        await this.sendPacket({
            type: PacketType.SampleStop,
            data: new Uint8Array(),
        });
    }
}

class UsbSerialConnection extends SerialConnection {
    constructor() {
        super();
        this.port = null;
        this.reader = null;
        this.writer = null;
    }

    async connect() {
        try {
            if (this.port) {
                await this.disconnect();
            }

            this.buffer = new Uint8Array();

            // Prompt user to select any serial port.
            this.port = await navigator.serial.requestPort();

            await this.port.open({ baudRate: 115200 });

            let reader = this.port.readable.getReader();
            this.reader = reader;

            (function loop() {
                    setTimeout(async () => {
                        try {
                            let {value, done} = await reader.read();
                            if (done) {
                                reader.releaseLock();
                                reader = null;
                                return;
                            }
                            await serialConnection.appendBuffer(value);
                        } catch (e) {
                            console.log(e);
                            reader.releaseLock();
                            reader = null;
                            return;
                        }
                        loop();
                    });
            })();

            const ackPacket = await this.sendPacket({
                type: PacketType.Startup,
                data: [0, 0]
            });

            if (ackPacket && ackPacket.type === PacketType.Ack) {
                console.log("Got startup ack successfully");
                this.isConnected = true;
                await this.updateConfig();
                return true;
            } else {
                console.log("Got bad startup ack");
                await this.disconnect();
                return false;
            }
        } catch (error) {
            // Case where user does not select a port or the port cannot be opened
            console.log(error);
            this.isConnected = false;
            return false;
        }
    }

    async sendPacketImpl(packet) {
        if (!this.port || this.port.writable.locked) {
            return;
        }

        try {
            const writer = this.port.writable.getWriter();
            await writer.write(packetToBytes(packet));
            writer.releaseLock();
        } catch (error) {
            console.log(error);
        }
    }

    async disconnect() {
        this.isConnected = false;

        try {
            // Tell the board to stop sending data
            // This makes it so the next reconnect will work
            await this.sampleStop();

            if (this.reader) {
                await this.reader.cancel();
                this.reader = null;
            }

            await this.port.close();
            this.port = null;

            this.reset();
        } catch (error) {
            console.log(error);
        }
    }
}

const SERVICE_UUID =                 "3b169a98-67ab-4a2a-b157-b4f6becb635d";
const CHARACTERISTIC_INDICATE_UUID = "30710eb4-e239-4e17-9250-8ad45f5ae174";
const CHARACTERISTIC_WRITE_UUID =    "36895b3a-4dea-461c-801a-0ef7bf10359e";

class BluetoothSerialConnection extends SerialConnection {
    constructor() {
        super();
        this.device = null;
    }

    async connect() {
        try {
            await BleClient.initialize();

            this.device = await BleClient.requestDevice({
                namePrefix: 'HuskerScope',
                optionalServices: [SERVICE_UUID]
            });

            await BleClient.connect(this.device.deviceId, (id) => {
                this.isConnected = false;
            });

            await BleClient.startNotifications(this.device.deviceId, SERVICE_UUID, CHARACTERISTIC_INDICATE_UUID, async (value) => {
                await this.appendBuffer(value);
            });

            const ackPacket = await this.sendPacket({
                type: PacketType.Startup,
                data: [0, 0]
            });

            if (ackPacket && ackPacket.type === PacketType.Ack) {
                console.log("Got startup ack successfully");
                this.isConnected = true;
                await this.updateConfig();
                return true;
            } else {
                console.log("Got bad startup ack");
                await this.disconnect();
                return false;
            }
        } catch (error) {
            this.isConnected = false;
            this.device = null;
            console.log(error);
            return false;
        }
    }

    async sendPacketImpl(packet) {
        try {
            const data = packetToBytes(packet);
            await BleClient.write(this.device.deviceId, SERVICE_UUID, CHARACTERISTIC_WRITE_UUID, data);
        } catch (error) {
            console.log(error);
        }
    }

    async disconnect() {
        this.isConnected = false;

        if (!this.device) {
            return;
        }

        try {
            await this.sampleStop();

            await BleClient.disconnect(this.device.deviceId);
            this.device = null;

            this.reset();
        } catch (error) {
            console.log(error);
        }
    }
}

// Attempt at a javascript interface
export let serialConnection = !isPlatform("mobile") ? new UsbSerialConnection() : new BluetoothSerialConnection();