import { squareOutline } from 'ionicons/icons';
import { useEffect, useRef } from 'react';

import { getCarrierFrequency, WAVETYPE } from '../State';

export interface FGAudioChannel {
  active: boolean,
  frequency: number,
  messageFrequency: number,
  amplitude: number,
  waveform: WAVETYPE,
  phase: number,
  modulation: boolean
}

interface FGAudioChannelProps extends FGAudioChannel {
  audioCtx: AudioContext,
  channel: "left" | "right",
  syncMultiplier: number,
  analyser?: AnalyserNode,
}

// Convert from [0, 360] to corresponding amount of delay in seconds
const transformPhase = (frequency: number, phase: number) => {
  return (1/frequency) * (phase/360 + 0.5);
}

export const FunctionGeneratorChannel = (props: FGAudioChannelProps) => {
  // Audio node refs
  const oscillator = useRef<OscillatorNode>(null!);
  const stereo = useRef<StereoPannerNode>(null!);
  const gain = useRef<GainNode>(null!);
  const delay = useRef<DelayNode>(null!);

  // Value refs
  const frequency = useRef<number>(440);
  const messageFrequency = useRef<number>(40);
  const amplitude = useRef<number>(100);
  const phase = useRef<number>(180);
  const modulation = useRef<boolean>(false);
  
  const fs = 48000;
  const L = 2048;
  const N = 2048;
  const fmult = 2.432;

  let fft = require('fft-js').fft;

  // Activate/deactivate
  useEffect(() => {
    // Is activating?
    if(props.audioCtx && props.active) {
      // Setup oscillator node
      let newOsc = props.audioCtx.createOscillator();

      if (props.waveform != "custom" as WAVETYPE) {
        newOsc.frequency.value = frequency.current;
        newOsc.type = props.waveform;
      }

      // Setup gain node
      let newGain = props.audioCtx.createGain();
      newGain.gain.value = amplitude.current;

      // Setup stereo node
      let newStereo = props.audioCtx.createStereoPanner();
      let offset: number = 0;
      switch(props.channel) {
        case "left": {
          offset = -1;
          break;
        }
        case "right": {
          offset = 1;
          break;
        }
        default: {
          offset = 0;
          break;
        }
      }

      newStereo.pan.value = offset;

      // Setup delay node
      let newDelay = props.audioCtx.createDelay();
      newDelay.delayTime.value = transformPhase(frequency.current, phase.current);

      // Save to refs
      oscillator.current = newOsc;
      gain.current = newGain;
      stereo.current = newStereo;
      delay.current = newDelay;

      // Connect nodes
      newOsc.connect(newGain);
      newGain.connect(newStereo);
      newStereo.connect(newDelay);
      newDelay.connect(props.audioCtx.destination);

      // Connect to analyser if it exists
      if(props.analyser) {
        newDelay.connect(props.analyser);
      }

      // Start playing at next integer timestamp at least 0.05 seconds from now
      // if the channels can be synced. Otherwise, start immediately.
      if(props.syncMultiplier) {
        newOsc.start(Math.ceil(props.audioCtx.currentTime + 0.05));
      } else {
        newOsc.start();
      }

      // Cleanup function
      return () => {
        newOsc.stop();
        newOsc.disconnect();
        newGain.disconnect();
        newStereo.disconnect();
        newDelay.disconnect();

        if(props.analyser) {
          props.analyser.disconnect();
        }
      };
    }
  }, [
    props.audioCtx, 
    props.waveform, 
    props.channel, 
    props.active, 
    props.analyser, 
    props.syncMultiplier
  ]);

  // Update parameter values
  useEffect(() => {
    // Update ref
    frequency.current = props.frequency;
    messageFrequency.current = props.messageFrequency;
    amplitude.current = props.amplitude;
    phase.current = props.phase;
    modulation.current = props.modulation;

    // If active, also update current oscillator
    if(!props.audioCtx || !props.active) { return; }
    
    if (props.waveform != "custom" as WAVETYPE) { 
      oscillator.current.frequency.value = frequency.current; 
      delay.current.delayTime.value = transformPhase(frequency.current, phase.current);
      gain.current.gain.value = amplitude.current;
      return;
    }

    let signal = new Float32Array(L);
    let real = new Float32Array(N/2);
    let imag = new Float32Array(N/2);

    oscillator.current.frequency.value = messageFrequency.current;
    let fc = frequency.current * 25 / messageFrequency.current * .94;
    let fm = fs / L;

    if (modulation.current) {
      for (let i = 0; i < L; i++) {
        signal[i] = Math.sin(2 * Math.PI * fc * i / fs) * 
        Math.sin(2 * Math.PI * fm * i / fs);
      }
    } else {
      let fi = .5 * frequency.current / messageFrequency.current;
      for (let i = 0; i < L; i++) {
        signal[i] = Math.sin(
          2 * Math.PI * fc * i / fs + fi * 
          Math.sin(2 * Math.PI * fm * i / fs) 
        );
      }
    }

    let response = fft(signal);

    for (let i = 0; i < N / 2; i++) {
      real[i] = response[i][0] * -2 * Math.PI / N;
      imag[i] = response[i][1] * -2 * Math.PI / N;
    }

    let newWave = props.audioCtx.createPeriodicWave(
      real, 
      imag, 
      {disableNormalization: true}
    );

    oscillator.current.setPeriodicWave(newWave);

    delay.current.delayTime.value = 0;

    gain.current.gain.value = amplitude.current * .2;
  }, [
    props.audioCtx, 
    props.active, 
    props.frequency, 
    props.messageFrequency, 
    props.amplitude, 
    props.phase, 
    props.modulation
  ]);

  return null;
};
