import { IonButton } from "@ionic/react";
import './Buttons.css';

type Props = {
  hidden: boolean,
  onClick: () => void
};

const FullscreenExitButton: React.FC<Props> = ({ hidden, onClick }) => {

  return (
    
    <IonButton className="flscrn-button-graph-full"
               onClick = {() => onClick()}           
               mode="ios" 
               fill="clear"
               hidden={hidden}>
      <img className="fullscreen-img" src={process.env.PUBLIC_URL + "/assets/fullscreen2.png"} alt=""></img>
    </IonButton>
    
  );
};

export default FullscreenExitButton;
